package com.pvparena;

import net.runelite.api.gameval.InterfaceID.PvpArenaStagingareaSupplies;
import net.runelite.api.gameval.InterfaceID.PvpArenaUnrankedduel;

/**
 * Centralised, per-build component ids for the two {@link Setup} builders, so every
 * widget assumption the Loadouts feature makes lives in one place.
 *
 * <p><b>VERIFY IN-GAME (see DESIGN.md "Feature 3" checklist).</b> Worn slots and the
 * spellbook display are reused from the proven Feature 2 path and are reliable. The
 * catalog is {@code _NITEMS_LIST} ({@link Screen#itemsList}) — confirmed in-game: the
 * "to add" highlights land on it. The catalog and the owned inventory are <b>separate</b>
 * areas: the owned inventory grid is {@code _NINVENTORY} ({@link Screen#inventory}), read
 * directly (DFS from that widget), not by exclusion — it is a sibling of {@code universe},
 * so a DFS from the root never reached it and inventory always read empty.
 */
final class ArenaWidgets
{
	/** Equipment slot index per worn-slot widget, in {@code _NSLOTn} order (n has gaps). */
	static final int[] WORN_SLOT_INDEX = {0, 1, 2, 3, 4, 5, 7, 9, 10, 12, 13};

	/** A builder screen, with per-build ({@code 0}/{@code 1}/{@code 2}) widget ids. */
	static final class Screen
	{
		final int universe;
		final int[] wornRoot;          // _NWORN — non-hidden => this build is shown
		final int[][] wornSlots;       // [build][WORN_SLOT_INDEX position] => _NSLOTn
		final int[] spellbookDisplay;  // _NSPELLBOOK_DISPLAY
		final int[] itemsList;         // _NITEMS_LIST — the catalog of selectable items
		final int[] inventory;         // _NINVENTORY — the owned supplies grid
		final int[] seek;              // _NSEEK — the catalog search input

		private Screen(int universe, int[] wornRoot, int[][] wornSlots, int[] spellbookDisplay,
			int[] itemsList, int[] inventory, int[] seek)
		{
			this.universe = universe;
			this.wornRoot = wornRoot;
			this.wornSlots = wornSlots;
			this.spellbookDisplay = spellbookDisplay;
			this.itemsList = itemsList;
			this.inventory = inventory;
			this.seek = seek;
		}
	}

	static final Screen UNRANKED = new Screen(
		PvpArenaUnrankedduel.UNIVERSE,
		new int[]{
			PvpArenaUnrankedduel._0WORN,
			PvpArenaUnrankedduel._1WORN,
			PvpArenaUnrankedduel._2WORN,
		},
		new int[][]{
			{
				PvpArenaUnrankedduel._0SLOT0, PvpArenaUnrankedduel._0SLOT1, PvpArenaUnrankedduel._0SLOT2,
				PvpArenaUnrankedduel._0SLOT3, PvpArenaUnrankedduel._0SLOT4, PvpArenaUnrankedduel._0SLOT5,
				PvpArenaUnrankedduel._0SLOT7, PvpArenaUnrankedduel._0SLOT9, PvpArenaUnrankedduel._0SLOT10,
				PvpArenaUnrankedduel._0SLOT12, PvpArenaUnrankedduel._0SLOT13,
			},
			{
				PvpArenaUnrankedduel._1SLOT0, PvpArenaUnrankedduel._1SLOT1, PvpArenaUnrankedduel._1SLOT2,
				PvpArenaUnrankedduel._1SLOT3, PvpArenaUnrankedduel._1SLOT4, PvpArenaUnrankedduel._1SLOT5,
				PvpArenaUnrankedduel._1SLOT7, PvpArenaUnrankedduel._1SLOT9, PvpArenaUnrankedduel._1SLOT10,
				PvpArenaUnrankedduel._1SLOT12, PvpArenaUnrankedduel._1SLOT13,
			},
			{
				PvpArenaUnrankedduel._2SLOT0, PvpArenaUnrankedduel._2SLOT1, PvpArenaUnrankedduel._2SLOT2,
				PvpArenaUnrankedduel._2SLOT3, PvpArenaUnrankedduel._2SLOT4, PvpArenaUnrankedduel._2SLOT5,
				PvpArenaUnrankedduel._2SLOT7, PvpArenaUnrankedduel._2SLOT9, PvpArenaUnrankedduel._2SLOT10,
				PvpArenaUnrankedduel._2SLOT12, PvpArenaUnrankedduel._2SLOT13,
			},
		},
		new int[]{
			PvpArenaUnrankedduel._0SPELLBOOK_DISPLAY,
			PvpArenaUnrankedduel._1SPELLBOOK_DISPLAY,
			PvpArenaUnrankedduel._2SPELLBOOK_DISPLAY,
		},
		new int[]{
			PvpArenaUnrankedduel._0ITEMS_LIST,
			PvpArenaUnrankedduel._1ITEMS_LIST,
			PvpArenaUnrankedduel._2ITEMS_LIST,
		},
		new int[]{
			PvpArenaUnrankedduel._0INVENTORY,
			PvpArenaUnrankedduel._1INVENTORY,
			PvpArenaUnrankedduel._2INVENTORY,
		},
		new int[]{
			PvpArenaUnrankedduel._0SEEK,
			PvpArenaUnrankedduel._1SEEK,
			PvpArenaUnrankedduel._2SEEK,
		});

	static final Screen STAGING = new Screen(
		PvpArenaStagingareaSupplies.UNIVERSE,
		new int[]{
			PvpArenaStagingareaSupplies._0WORN,
			PvpArenaStagingareaSupplies._1WORN,
			PvpArenaStagingareaSupplies._2WORN,
		},
		new int[][]{
			{
				PvpArenaStagingareaSupplies._0SLOT0, PvpArenaStagingareaSupplies._0SLOT1, PvpArenaStagingareaSupplies._0SLOT2,
				PvpArenaStagingareaSupplies._0SLOT3, PvpArenaStagingareaSupplies._0SLOT4, PvpArenaStagingareaSupplies._0SLOT5,
				PvpArenaStagingareaSupplies._0SLOT7, PvpArenaStagingareaSupplies._0SLOT9, PvpArenaStagingareaSupplies._0SLOT10,
				PvpArenaStagingareaSupplies._0SLOT12, PvpArenaStagingareaSupplies._0SLOT13,
			},
			{
				PvpArenaStagingareaSupplies._1SLOT0, PvpArenaStagingareaSupplies._1SLOT1, PvpArenaStagingareaSupplies._1SLOT2,
				PvpArenaStagingareaSupplies._1SLOT3, PvpArenaStagingareaSupplies._1SLOT4, PvpArenaStagingareaSupplies._1SLOT5,
				PvpArenaStagingareaSupplies._1SLOT7, PvpArenaStagingareaSupplies._1SLOT9, PvpArenaStagingareaSupplies._1SLOT10,
				PvpArenaStagingareaSupplies._1SLOT12, PvpArenaStagingareaSupplies._1SLOT13,
			},
			{
				PvpArenaStagingareaSupplies._2SLOT0, PvpArenaStagingareaSupplies._2SLOT1, PvpArenaStagingareaSupplies._2SLOT2,
				PvpArenaStagingareaSupplies._2SLOT3, PvpArenaStagingareaSupplies._2SLOT4, PvpArenaStagingareaSupplies._2SLOT5,
				PvpArenaStagingareaSupplies._2SLOT7, PvpArenaStagingareaSupplies._2SLOT9, PvpArenaStagingareaSupplies._2SLOT10,
				PvpArenaStagingareaSupplies._2SLOT12, PvpArenaStagingareaSupplies._2SLOT13,
			},
		},
		new int[]{
			PvpArenaStagingareaSupplies._0SPELLBOOK_DISPLAY,
			PvpArenaStagingareaSupplies._1SPELLBOOK_DISPLAY,
			PvpArenaStagingareaSupplies._2SPELLBOOK_DISPLAY,
		},
		new int[]{
			PvpArenaStagingareaSupplies._0ITEMS_LIST,
			PvpArenaStagingareaSupplies._1ITEMS_LIST,
			PvpArenaStagingareaSupplies._2ITEMS_LIST,
		},
		new int[]{
			PvpArenaStagingareaSupplies._0INVENTORY,
			PvpArenaStagingareaSupplies._1INVENTORY,
			PvpArenaStagingareaSupplies._2INVENTORY,
		},
		new int[]{
			PvpArenaStagingareaSupplies._0SEEK,
			PvpArenaStagingareaSupplies._1SEEK,
			PvpArenaStagingareaSupplies._2SEEK,
		});

	static final Screen[] SCREENS = {UNRANKED, STAGING};

	/** Whether {@code componentId} is a catalog search ({@code _NSEEK}) button of either screen. */
	static boolean isSeekWidget(int componentId)
	{
		for (Screen s : SCREENS)
		{
			for (int id : s.seek)
			{
				if (id == componentId)
				{
					return true;
				}
			}
		}
		return false;
	}

	private ArenaWidgets()
	{
	}
}

package com.pvparena;

import lombok.Getter;

/**
 * The three fixed PvP Arena account builds, selected in-game by
 * {@code VarbitID.PVPA_TRANSMIT_BUILD} (value {@code 0}/{@code 1}/{@code 2} -> setup
 * panel {@code _0}/{@code _1}/{@code _2} / loadout slot A/B/C). Used only to group and
 * label {@link Loadout}s; loadouts are <b>not</b> locked to a build (see DESIGN.md
 * "Feature 3 -> Build context").
 *
 * <p>VERIFY IN-GAME: the exact value-&gt;label order (which of 0/1/2 is Pure, etc.).
 * If wrong, only the labels here need swapping.
 */
@Getter
enum Build
{
	MAX_MED(0, "Max/Med"),
	ZERKER(1, "Zerker"),
	PURE(2, "Pure");

	private final int value;
	private final String label;

	Build(int value, String label)
	{
		this.value = value;
		this.label = label;
	}

	static Build fromValue(int value)
	{
		for (Build b : values())
		{
			if (b.value == value)
			{
				return b;
			}
		}
		return null;
	}

	static String labelFor(int value)
	{
		final Build b = fromValue(value);
		return b == null ? "Build " + value : b.label;
	}
}

package com.pvparena;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;

/**
 * Feature 3 (Loadouts) — collapses the arena catalog ({@code _NITEMS_LIST}) to just the
 * rows whose item belongs to the active loadout, so the player sees only what to add.
 *
 * <p>Unlike the rest of the feature (overlay-only) this <b>mutates widgets</b> — hide +
 * repack — so it is built to be fully reversible: {@link #clear()} restores every touched
 * widget's hidden flag and original-Y plus the list's scroll height.
 *
 * <p>The catalog is a flat scroll list (verified in-game 2026-06): ~460 rows, ~4 widgets
 * each, all direct dynamic-children of the list, every widget's {@code originalY} an exact
 * multiple of {@value #STRIDE} equal to {@code rowIndex * STRIDE}. Filtering groups children
 * by that band, hides non-loadout rows, repacks survivors into a gap-free {@code 0..n} run
 * and shrinks the scroll height. The game rebuilds the list on its own (item add/remove,
 * build switch), resetting our work; {@link #maintain} re-applies idempotently — a
 * scroll-height check short-circuits when the list is still filtered — so the caller can
 * poll it every client tick. All methods must run on the client thread.
 */
@Singleton
class CatalogFilter
{
	private static final int STRIDE = 32;

	private final Client client;

	/** Pre-mutation state of one touched widget, for {@link #restore()}. */
	private static final class Saved
	{
		final Widget widget;
		final boolean hidden;
		final int originalY;

		Saved(Widget widget)
		{
			this.widget = widget;
			this.hidden = widget.isSelfHidden();
			this.originalY = widget.getOriginalY();
		}
	}

	private final List<Saved> saved = new ArrayList<>();
	private boolean applied;
	private int appliedBuild = -1;
	private List<Integer> appliedKeep;
	private int appliedListId = -1;
	private int appliedScrollHeight = -1;
	private int originalScrollHeight = -1;

	@Inject
	CatalogFilter(Client client)
	{
		this.client = client;
	}

	/**
	 * Ensures the {@code build} catalog shows only rows whose item is in {@code orderedKeep},
	 * repacked into that exact order (index 0 nearest the top). Cheap and idempotent when
	 * already applied to the same context; re-applies after the game rebuilds the list.
	 */
	void maintain(ArenaWidgets.Screen s, int build, List<Integer> orderedKeep)
	{
		if (orderedKeep == null || build < 0 || build >= s.itemsList.length)
		{
			return;
		}
		final Widget list = client.getWidget(s.itemsList[build]);
		if (list == null)
		{
			return;
		}

		if (applied)
		{
			if (build != appliedBuild || !orderedKeep.equals(appliedKeep))
			{
				restore(); // different context/order: undo (self-guards staleness), then re-apply
			}
			else if (list.getScrollHeight() == appliedScrollHeight)
			{
				return; // still filtered as intended
			}
			else
			{
				forget(); // same context but the game rebuilt: cached widgets are stale
			}
		}

		applyFresh(list, build, orderedKeep);
	}

	/** Restores the catalog if filtered; safe to call every tick when inactive. */
	void clear()
	{
		if (applied)
		{
			restore();
		}
	}

	private void applyFresh(Widget list, int build, List<Integer> orderedKeep)
	{
		final Widget[] kids = list.getDynamicChildren();
		if (kids == null || kids.length == 0)
		{
			return;
		}

		// Desired display rank per item id (lower = nearer the top of the list).
		final Map<Integer, Integer> rank = new HashMap<>();
		for (int i = 0; i < orderedKeep.size(); i++)
		{
			rank.putIfAbsent(orderedKeep.get(i), i);
		}

		// Group children into rows by their stride band, ascending (TreeMap = catalog order).
		final TreeMap<Integer, List<Widget>> rows = new TreeMap<>();
		for (Widget k : kids)
		{
			if (k != null)
			{
				rows.computeIfAbsent(Math.floorDiv(k.getOriginalY(), STRIDE), r -> new ArrayList<>()).add(k);
			}
		}

		// Snapshot every touched widget, hide non-kept rows, collect the kept rows.
		saved.clear();
		originalScrollHeight = list.getScrollHeight();
		final List<List<Widget>> kept = new ArrayList<>();
		for (List<Widget> row : rows.values())
		{
			for (Widget w : row)
			{
				saved.add(new Saved(w));
			}
			if (rank.containsKey(rowItemId(row)))
			{
				kept.add(row);
			}
			else
			{
				for (Widget w : row)
				{
					w.setHidden(true);
				}
			}
		}

		// Repack survivors into a gap-free run, orderedKeep index 0 topmost (verified in-game:
		// smaller originalY renders nearer the top).
		kept.sort(Comparator.comparingInt(row -> rank.getOrDefault(rowItemId(row), Integer.MAX_VALUE)));
		int newIndex = 0;
		for (List<Widget> row : kept)
		{
			final int band = Math.floorDiv(row.get(0).getOriginalY(), STRIDE) * STRIDE;
			for (Widget w : row)
			{
				w.setHidden(false);
				w.setOriginalY(newIndex * STRIDE + (w.getOriginalY() - band));
				w.revalidate();
			}
			newIndex++;
		}

		appliedScrollHeight = newIndex * STRIDE;
		list.setScrollHeight(appliedScrollHeight);
		list.revalidateScroll();

		applied = true;
		appliedBuild = build;
		appliedKeep = new ArrayList<>(orderedKeep);
		appliedListId = list.getId();
	}

	private void restore()
	{
		// Re-fetch live: if the list was rebuilt its scroll height differs from what we set,
		// meaning our cached widgets are detached/stale and the list is already default.
		final Widget live = appliedListId < 0 ? null : client.getWidget(appliedListId);
		if (live == null || live.getScrollHeight() != appliedScrollHeight)
		{
			forget();
			return;
		}

		for (Saved sv : saved)
		{
			sv.widget.setHidden(sv.hidden);
			sv.widget.setOriginalY(sv.originalY);
			sv.widget.revalidate();
		}
		if (originalScrollHeight >= 0)
		{
			live.setScrollHeight(originalScrollHeight);
			live.revalidateScroll();
		}
		forget();
	}

	private void forget()
	{
		saved.clear();
		applied = false;
		appliedBuild = -1;
		appliedKeep = null;
		appliedListId = -1;
		appliedScrollHeight = -1;
		originalScrollHeight = -1;
	}

	private static int rowItemId(List<Widget> row)
	{
		for (Widget w : row)
		{
			if (w.getItemId() > 0)
			{
				return w.getItemId();
			}
		}
		return -1;
	}

	/**
	 * Item id of the catalog row an {@code Add} click targets, or -1. The clicked op hotspot
	 * carries no item id (verified in-game: the icon is a separate widget sharing the row's
	 * {@value #STRIDE}px band) and the menu entry's own item id is unset for this bespoke CC_OP,
	 * so locate the row from the list component (the click's param1) and clicked child (param0),
	 * then read the icon sibling — the same source {@link #applyFresh} groups rows by. Client
	 * thread only; null/bounds-safe so a non-catalog click just yields -1.
	 */
	int clickedRowItemId(int listComponentId, int hotspotIndex)
	{
		final Widget list = client.getWidget(listComponentId);
		if (list == null)
		{
			return -1;
		}
		final Widget[] kids = list.getDynamicChildren();
		if (kids == null || hotspotIndex < 0 || hotspotIndex >= kids.length || kids[hotspotIndex] == null)
		{
			return -1;
		}

		final int rowY = kids[hotspotIndex].getOriginalY();
		final int[] ys = new int[kids.length];
		final int[] itemIds = new int[kids.length];
		final boolean[] hidden = new boolean[kids.length];
		for (int i = 0; i < kids.length; i++)
		{
			ys[i] = kids[i] == null ? Integer.MIN_VALUE : kids[i].getOriginalY();
			itemIds[i] = kids[i] == null ? -1 : kids[i].getItemId();
			hidden[i] = kids[i] == null || kids[i].isSelfHidden();
		}
		return itemIdSharingRow(rowY, ys, itemIds, hidden);
	}

	/**
	 * Item id of the first visible item-bearing entry whose {@code ys[i]} equals {@code rowY}, or
	 * -1. Confirmed in-game 2026-08-11: an {@code Add} click's param0 is the dense index of a bare
	 * op hotspot (no item id) which shares its {@code originalY} with the row's icon widget; repack
	 * moves a whole row's widgets together and hides non-loadout rows, so the clicked item is the
	 * non-hidden icon on the same {@code originalY}. Factored out (pure) for unit tests: hidden rows
	 * at a colliding Y must be skipped, and only one visible item can occupy a row.
	 */
	static int itemIdSharingRow(int rowY, int[] ys, int[] itemIds, boolean[] hidden)
	{
		for (int i = 0; i < itemIds.length; i++)
		{
			if (itemIds[i] > 0 && !hidden[i] && ys[i] == rowY)
			{
				return itemIds[i];
			}
		}
		return -1;
	}
}

package com.pvparena;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * A saved, named, persisted snapshot of a {@link Setup} (worn equipment, inventory
 * supplies + quantities, spellbook) that the plugin stores and lets the player recall.
 * Grouped for display by the {@link Build} it was saved from.
 *
 * <p>Worn and inventory are stored distinctly for snapshot fidelity, but matching
 * flattens them via {@link #bag()} (total possession, see ADR-0002). Serialized to the
 * {@code pvparena} config as JSON.
 */
@Data
@NoArgsConstructor
class Loadout
{
	private String id;
	private String name;
	/** Build value 0/1/2 it was saved from (grouping/display only; see {@link Build}). */
	private int build;
	/** Spellbook display label text (e.g. {@code "Ancient Magicks"}); null if unknown. */
	private String spellbook;
	private List<WornItem> worn = new ArrayList<>();
	private List<InvItem> inventory = new ArrayList<>();
	private long savedAt;

	/**
	 * Flattens worn + inventory into a single {@code itemId -> total quantity} multiset.
	 * Matching is by total possession, ignoring worn-vs-inventory placement (ADR-0002).
	 */
	Map<Integer, Integer> bag()
	{
		final Map<Integer, Integer> bag = new HashMap<>();
		if (worn != null)
		{
			for (WornItem w : worn)
			{
				bag.merge(w.getItemId(), Math.max(1, w.getQuantity()), Integer::sum);
			}
		}
		if (inventory != null)
		{
			for (InvItem i : inventory)
			{
				bag.merge(i.getItemId(), Math.max(1, i.getQuantity()), Integer::sum);
			}
		}
		return bag;
	}

	/**
	 * Collapses duplicate inventory entries (same {@code itemId}) into one, summing quantities,
	 * so a bag holding four separate sharks becomes a single {@code qty 4} entry. Since
	 * {@link InvItem} carries no slot/position, duplicate entries are pure redundancy — this is
	 * a lossless normalization that shortens serialized codes (see ADR-0004).
	 *
	 * <p>Preserves first-seen order for deterministic, byte-identical output, and clamps each
	 * entry to {@code >= 1} before summing — exactly what {@link #bag()} does per entry — so a
	 * collapsed list feeds {@code bag()} identically to the uncollapsed original for every input
	 * (including a hand-forged code with a non-positive quantity). Pure and idempotent; never
	 * mutates {@code items}.
	 */
	static List<InvItem> collapseInventory(List<InvItem> items)
	{
		final Map<Integer, Integer> byId = new LinkedHashMap<>();
		if (items != null)
		{
			for (InvItem i : items)
			{
				byId.merge(i.getItemId(), Math.max(1, i.getQuantity()), Integer::sum);
			}
		}

		final List<InvItem> out = new ArrayList<>(byId.size());
		for (Map.Entry<Integer, Integer> e : byId.entrySet())
		{
			out.add(new InvItem(e.getKey(), e.getValue()));
		}
		return out;
	}

	/** Total item count across worn + inventory (for empty-loadout checks / display). */
	int itemCount()
	{
		int n = 0;
		for (int q : bag().values())
		{
			n += q;
		}
		return n;
	}

	/** A worn-equipment entry. {@code slot} is the equipment slot id; quantity covers ammo. */
	@Data
	@NoArgsConstructor
	@AllArgsConstructor
	static class WornItem
	{
		private int slot;
		private int itemId;
		private int quantity;
	}

	/** An inventory supply stack. */
	@Data
	@NoArgsConstructor
	@AllArgsConstructor
	static class InvItem
	{
		private int itemId;
		private int quantity;
	}
}

package com.pvparena;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Base64;
import java.util.List;
import java.util.zip.DataFormatException;
import java.util.zip.Deflater;
import java.util.zip.Inflater;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Encodes a single {@link Loadout} to, and decodes it from, a portable Loadout code:
 * {@code pvpa-loadout-v1:} followed by {@code Base64(JSON)} of a {@link LoadoutCode} envelope
 * (see ADR-0004). The envelope is deliberately decoupled from the internal {@link Loadout},
 * so the wire format survives internal refactors; only the leaf item types are reused.
 *
 * <p>Item ids are trusted, not validated against the item cache: unplaceable items fail soft
 * downstream at load time (via {@code unlocatableCount}), exactly like a hand-built loadout.
 */
@Singleton
final class LoadoutCodec
{
	/** Magic prefix, minus the version integer and colon: {@code pvpa-loadout-v}. */
	static final String PREFIX = "pvpa-loadout-v";
	/**
	 * The schema version this plugin writes. Encode always emits this; decode still accepts every
	 * released version back to {@code 1} (see ADR-0005). v1 payload is {@code Base64(JSON)};
	 * v2 payload is {@code Base64(raw-DEFLATE(JSON))} of the same {@link LoadoutCode} envelope.
	 */
	static final int VERSION = 2;

	/** The client's shared {@link Gson} (plugin hub forbids fresh instances). */
	private final Gson gson;

	@Inject
	LoadoutCodec(Gson gson)
	{
		this.gson = gson;
	}

	/** Produces the shareable code for {@code loadout} ({@code id}/{@code savedAt} are omitted). */
	String encode(Loadout loadout)
	{
		final LoadoutCode code = new LoadoutCode();
		code.setName(loadout.getName());
		code.setBuild(loadout.getBuild());
		code.setSpellbook(loadout.getSpellbook());
		code.setWorn(loadout.getWorn());
		// Collapse defensively: loadouts persisted before this normalization existed still hold
		// one entry per inventory slot, so this keeps their exported codes short too. A copy is
		// produced (see Loadout.collapseInventory), so the cached loadout is never mutated.
		code.setInventory(Loadout.collapseInventory(loadout.getInventory()));

		final byte[] json = gson.toJson(code).getBytes(StandardCharsets.UTF_8);
		// v2: raw DEFLATE the JSON before Base64 (ADR-0005). Deterministic for a fixed input, so
		// the same loadout still produces a byte-identical code.
		return PREFIX + VERSION + ':' + Base64.getEncoder().encodeToString(deflate(json));
	}

	/**
	 * Parses {@code raw} into a fresh {@link Loadout} with no {@code id}/{@code savedAt} — the
	 * caller mints those via {@link LoadoutManager#add}. Throws {@link LoadoutCodecException}
	 * with {@link LoadoutCodecException.Reason#NEWER_VERSION} for a recognized-but-newer
	 * version, or {@link LoadoutCodecException.Reason#INVALID} for anything else.
	 */
	Loadout decode(String raw) throws LoadoutCodecException
	{
		if (raw == null)
		{
			throw invalid();
		}

		final String s = raw.trim();
		if (!s.startsWith(PREFIX))
		{
			throw invalid();
		}

		final int colon = s.indexOf(':', PREFIX.length());
		if (colon < 0)
		{
			throw invalid();
		}

		final int version = parseVersion(s.substring(PREFIX.length(), colon));
		if (version > VERSION)
		{
			throw new LoadoutCodecException(LoadoutCodecException.Reason.NEWER_VERSION);
		}
		if (version < 1)
		{
			// Unparseable or zero: no decode path exists, so it is simply invalid.
			throw invalid();
		}

		// Every released version decodes to the same LoadoutCode envelope; only the byte pipeline
		// differs. v1 is Base64(JSON); v2 adds a raw-DEFLATE layer under the Base64 (ADR-0005).
		final byte[] payload = base64(s.substring(colon + 1));
		final byte[] json = version == 1 ? payload : inflate(payload);
		final LoadoutCode code = parseJson(json);

		final boolean noWorn = code.getWorn() == null || code.getWorn().isEmpty();
		final boolean noInventory = code.getInventory() == null || code.getInventory().isEmpty();
		if (noWorn && noInventory)
		{
			throw invalid();
		}

		final Loadout out = new Loadout();
		out.setName(code.getName());
		out.setBuild(code.getBuild());
		out.setSpellbook(code.getSpellbook());
		out.setWorn(code.getWorn() == null ? new ArrayList<>() : code.getWorn());
		out.setInventory(code.getInventory() == null ? new ArrayList<>() : code.getInventory());
		return out;
	}

	/** {@code -1} if the version segment is not a non-negative integer. */
	private static int parseVersion(String segment)
	{
		if (segment.isEmpty())
		{
			return -1;
		}
		for (int i = 0; i < segment.length(); i++)
		{
			if (!Character.isDigit(segment.charAt(i)))
			{
				return -1;
			}
		}
		try
		{
			return Integer.parseInt(segment);
		}
		catch (NumberFormatException e)
		{
			return -1; // overflow -> unrecognized version
		}
	}

	private static byte[] base64(String payload) throws LoadoutCodecException
	{
		try
		{
			return Base64.getDecoder().decode(payload);
		}
		catch (IllegalArgumentException e)
		{
			throw invalid();
		}
	}

	private LoadoutCode parseJson(byte[] json) throws LoadoutCodecException
	{
		final LoadoutCode code;
		try
		{
			code = gson.fromJson(new String(json, StandardCharsets.UTF_8), LoadoutCode.class);
		}
		catch (JsonSyntaxException e)
		{
			throw invalid();
		}
		if (code == null)
		{
			throw invalid();
		}
		return code;
	}

	/** Raw DEFLATE (nowrap: no zlib header/checksum) at max level; deterministic for a fixed input. */
	private static byte[] deflate(byte[] data)
	{
		final Deflater deflater = new Deflater(Deflater.BEST_COMPRESSION, true);
		deflater.setInput(data);
		deflater.finish();

		final ByteArrayOutputStream out = new ByteArrayOutputStream(Math.max(32, data.length / 3));
		final byte[] buf = new byte[2048];
		while (!deflater.finished())
		{
			out.write(buf, 0, deflater.deflate(buf));
		}
		deflater.end();
		return out.toByteArray();
	}

	/** Inverse of {@link #deflate}; a corrupt or truncated stream is an invalid code, not a crash. */
	private static byte[] inflate(byte[] compressed) throws LoadoutCodecException
	{
		final Inflater inflater = new Inflater(true);
		// A nowrap inflater needs one extra dummy byte past the end of the raw DEFLATE stream
		// (a documented ZLIB requirement); without it a valid stream never reaches finished().
		inflater.setInput(Arrays.copyOf(compressed, compressed.length + 1));

		final ByteArrayOutputStream out = new ByteArrayOutputStream(Math.max(64, compressed.length * 3));
		final byte[] buf = new byte[2048];
		try
		{
			while (!inflater.finished())
			{
				final int n = inflater.inflate(buf);
				if (n > 0)
				{
					out.write(buf, 0, n);
				}
				else if (!inflater.finished())
				{
					// No progress and not done: the stream is truncated or wants a dictionary.
					throw invalid();
				}
			}
		}
		catch (DataFormatException e)
		{
			throw invalid();
		}
		finally
		{
			inflater.end();
		}
		return out.toByteArray();
	}

	private static LoadoutCodecException invalid()
	{
		return new LoadoutCodecException(LoadoutCodecException.Reason.INVALID);
	}

	/**
	 * The wire envelope (ADR-0004): top-level fields only, mirroring {@link Loadout} minus
	 * {@code id}/{@code savedAt}. The leaf item types are reused unchanged.
	 */
	@Data
	@NoArgsConstructor
	static class LoadoutCode
	{
		private String name;
		private int build;
		private String spellbook;
		private List<Loadout.WornItem> worn = new ArrayList<>();
		private List<Loadout.InvItem> inventory = new ArrayList<>();
	}
}

package com.pvparena;

/**
 * Thrown when a {@link com.pvparena.LoadoutCodec.LoadoutCode Loadout code} cannot be decoded.
 * {@link #getReason()} separates a generically invalid code from one produced by a newer
 * plugin version, so the caller can pick a matching message (see ADR-0004).
 */
class LoadoutCodecException extends Exception
{
	/** Why a code was rejected. */
	enum Reason
	{
		/** Bad prefix, bad Base64, bad JSON, an unknown version, or an empty (no-item) payload. */
		INVALID,
		/** A recognized prefix carrying a version newer than this plugin understands. */
		NEWER_VERSION
	}

	private final Reason reason;

	LoadoutCodecException(Reason reason)
	{
		super(reason.name());
		this.reason = reason;
	}

	Reason getReason()
	{
		return reason;
	}
}

package com.pvparena;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Pure diff between a target {@link Loadout} bag and the current {@link Setup} bag
 * (total possession, see ADR-0002 and DESIGN.md "Feature 3 -> Matching / diff").
 * Unit-tested; no client dependencies.
 */
class LoadoutDiff
{
	/** itemId -&gt; how many MORE are needed (drives catalog "to add" highlights). */
	private final Map<Integer, Integer> toAdd;
	/** itemId -&gt; how many too MANY are present (drives setup excess marks). */
	private final Map<Integer, Integer> excess;
	private final boolean spellbookMismatch;

	private LoadoutDiff(Map<Integer, Integer> toAdd, Map<Integer, Integer> excess, boolean spellbookMismatch)
	{
		this.toAdd = toAdd;
		this.excess = excess;
		this.spellbookMismatch = spellbookMismatch;
	}

	Map<Integer, Integer> toAdd()
	{
		return Collections.unmodifiableMap(toAdd);
	}

	Map<Integer, Integer> excess()
	{
		return Collections.unmodifiableMap(excess);
	}

	boolean spellbookMismatch()
	{
		return spellbookMismatch;
	}

	/** How many more of {@code itemId} to add (0 if none). */
	int needFor(int itemId)
	{
		return toAdd.getOrDefault(itemId, 0);
	}

	/** Whether {@code itemId} is present in excess / unwanted in the setup. */
	boolean isExcess(int itemId)
	{
		return excess.containsKey(itemId);
	}

	/**
	 * Full match: nothing to add, nothing in excess, and the spellbook matches. The
	 * trigger for auto-clearing the {@link LoadoutManager#getActive() active loadout}.
	 */
	boolean isFullMatch()
	{
		return toAdd.isEmpty() && excess.isEmpty() && !spellbookMismatch;
	}

	/**
	 * @param want          target bag (itemId -&gt; qty) from the loadout
	 * @param have          current bag (itemId -&gt; qty) from the live setup
	 * @param wantSpellbook loadout spellbook label (nullable)
	 * @param haveSpellbook current setup spellbook label (nullable)
	 */
	static LoadoutDiff compute(Map<Integer, Integer> want, Map<Integer, Integer> have,
		String wantSpellbook, String haveSpellbook)
	{
		final Map<Integer, Integer> toAdd = new HashMap<>();
		final Map<Integer, Integer> excess = new HashMap<>();

		for (Map.Entry<Integer, Integer> e : want.entrySet())
		{
			final int need = e.getValue() - have.getOrDefault(e.getKey(), 0);
			if (need > 0)
			{
				toAdd.put(e.getKey(), need);
			}
		}

		for (Map.Entry<Integer, Integer> e : have.entrySet())
		{
			final int over = e.getValue() - want.getOrDefault(e.getKey(), 0);
			if (over > 0)
			{
				excess.put(e.getKey(), over);
			}
		}

		// Reuse Feature 2's case-insensitive, fail-quiet label compare: a null/blank on
		// either side yields no mismatch (we never flag an unknown spellbook).
		final boolean spellbookMismatch = SpellbookMismatchOverlay.isMismatch(wantSpellbook, haveSpellbook);

		return new LoadoutDiff(toAdd, excess, spellbookMismatch);
	}
}

package com.pvparena;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Persistence + active-state for {@link Loadout}s. Stored globally (not RSProfile-scoped,
 * see ADR-0003) as a JSON list under the {@code pvparena} config group. Holds the single
 * {@link #getActive() active loadout} in memory (ephemeral, by id).
 */
@Slf4j
@Singleton
class LoadoutManager
{
	/** Distinct from the {@code loadouts} feature-toggle config key: sharing it clobbers the toggle. */
	static final String KEY = "savedLoadouts";
	private static final Type LIST_TYPE = new TypeToken<List<Loadout>>()
	{
	}.getType();

	private final ConfigManager configManager;
	private final Gson gson;

	/** Lazily-loaded, authoritative in-memory copy; persisted on every mutation. */
	private List<Loadout> cache;
	/** Id of the active loadout (the one loaded for comparison), or null. */
	private String activeId;
	/** Whether the catalog filter is engaged for the active loadout (auto-on when loaded). */
	private boolean filterOn;

	@Inject
	LoadoutManager(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	synchronized List<Loadout> getAll()
	{
		ensureLoaded();
		return new ArrayList<>(cache);
	}

	synchronized List<Loadout> forBuild(int build)
	{
		ensureLoaded();
		final List<Loadout> out = new ArrayList<>();
		for (Loadout l : cache)
		{
			if (l.getBuild() == build)
			{
				out.add(l);
			}
		}
		return out;
	}

	synchronized Loadout byId(String id)
	{
		ensureLoaded();
		if (id == null)
		{
			return null;
		}
		for (Loadout l : cache)
		{
			if (id.equals(l.getId()))
			{
				return l;
			}
		}
		return null;
	}

	/** Persists {@code snapshot} as a new loadout with the given display name. */
	synchronized Loadout add(Loadout snapshot, String name)
	{
		ensureLoaded();
		snapshot.setId(UUID.randomUUID().toString());
		snapshot.setName(name);
		snapshot.setSavedAt(System.currentTimeMillis());
		snapshot.setInventory(Loadout.collapseInventory(snapshot.getInventory()));
		cache.add(snapshot);
		persist();
		return snapshot;
	}

	synchronized void delete(String id)
	{
		ensureLoaded();
		cache.removeIf(l -> id != null && id.equals(l.getId()));
		if (id != null && id.equals(activeId))
		{
			activeId = null;
			filterOn = false;
		}
		persist();
	}

	synchronized void rename(String id, String name)
	{
		final Loadout l = byId(id);
		if (l != null)
		{
			l.setName(name);
			persist();
		}
	}

	/** Overwrites an existing loadout's contents from a freshly-read setup snapshot. */
	synchronized void update(String id, Loadout snapshot)
	{
		final Loadout l = byId(id);
		if (l != null)
		{
			l.setBuild(snapshot.getBuild());
			l.setSpellbook(snapshot.getSpellbook());
			l.setWorn(snapshot.getWorn());
			l.setInventory(Loadout.collapseInventory(snapshot.getInventory()));
			l.setSavedAt(System.currentTimeMillis());
			persist();
		}
	}

	synchronized Loadout getActive()
	{
		return byId(activeId);
	}

	synchronized void setActive(Loadout l)
	{
		activeId = l == null ? null : l.getId();
		filterOn = l != null; // catalog filter engages automatically on load
	}

	synchronized void clearActive()
	{
		activeId = null;
		filterOn = false;
	}

	synchronized boolean isActive(Loadout l)
	{
		return l != null && l.getId() != null && l.getId().equals(activeId);
	}

	/** Whether the catalog filter is engaged (only meaningful while a loadout is active). */
	synchronized boolean isFilterOn()
	{
		return activeId != null && filterOn;
	}

	synchronized void setFilterOn(boolean on)
	{
		filterOn = on;
	}

	private void ensureLoaded()
	{
		if (cache != null)
		{
			return;
		}

		final String json = configManager.getConfiguration(PvpArenaConfig.GROUP, KEY);
		List<Loadout> parsed = null;
		if (json != null && !json.isEmpty())
		{
			try
			{
				parsed = gson.fromJson(json, LIST_TYPE);
			}
			catch (JsonSyntaxException e)
			{
				log.warn("Could not parse stored loadouts, starting empty", e);
			}
		}
		cache = parsed != null ? parsed : new ArrayList<>();
	}

	private void persist()
	{
		configManager.setConfiguration(PvpArenaConfig.GROUP, KEY, gson.toJson(cache, LIST_TYPE));
	}
}

package com.pvparena;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Feature 3 — paints the load diff while a {@link Setup builder} is open and a
 * {@link LoadoutManager#getActive() loadout is active}: green outline (covering the
 * whole catalog option, icon + text) with a required-count when more than one is
 * needed, and a red outline over excess/unwanted setup items and a differing spellbook.
 * While the catalog is filtered ({@link LoadoutManager#isFilterOn()}) the to-add outline
 * is suppressed — every visible row already belongs to the loadout — leaving just the count.
 * Re-evaluates every frame, so counts fall and outlines clear as the player adds items.
 * Auto-clears the active loadout on full match. Overlay-only, fully reversible.
 */
class LoadoutOverlay extends Overlay
{
	private static final Color ADD_COLOR = new Color(0, 200, 0);
	private static final Color EXCESS_COLOR = Color.RED;
	private static final Stroke STROKE = new BasicStroke(2f);
	private static final Font COUNT_FONT = FontManager.getRunescapeSmallFont();
	private static final long MATCH_CONFIRM_MS = 2500L;

	private final Client client;
	private final PvpArenaConfig config;
	private final PvpArenaPlugin plugin;
	private final LoadoutManager manager;
	private final SetupReader reader;
	private final ItemManager itemManager;

	/** Needed items the current catalog had no row for; read by the panel for its note. */
	@Getter
	private volatile int lastUnlocatable;
	@Getter
	private volatile String lastUnlocatableActiveId;

	private long matchConfirmUntil;
	/** Id the match-tracking is armed for, and whether it has been seen unmatched since. */
	private String armedId;
	private boolean sawUnmatched;

	@Inject
	LoadoutOverlay(Client client, PvpArenaConfig config, PvpArenaPlugin plugin,
		LoadoutManager manager, SetupReader reader, ItemManager itemManager)
	{
		this.client = client;
		this.config = config;
		this.plugin = plugin;
		this.manager = manager;
		this.reader = reader;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.loadouts() || !plugin.inPvpArena())
		{
			return null;
		}

		final ArenaWidgets.Screen screen = reader.openScreen();
		if (screen == null)
		{
			lastUnlocatable = 0;
			return null;
		}

		// Brief "matched" confirmation persists after auto-clear (when active is null).
		if (System.currentTimeMillis() < matchConfirmUntil)
		{
			drawMatchedConfirmation(g, screen);
		}

		final Loadout active = manager.getActive();
		if (active == null)
		{
			lastUnlocatable = 0;
			armedId = null;
			sawUnmatched = false;
			return null;
		}

		// Re-arm match tracking whenever a different loadout is loaded.
		if (!active.getId().equals(armedId))
		{
			armedId = active.getId();
			sawUnmatched = false;
		}

		final int build = reader.activeBuild(screen);
		final List<SetupReader.ItemWidget> worn = reader.wornItems(screen, build);
		final List<SetupReader.ItemWidget> inventory = reader.inventoryItems(screen, build);
		final List<SetupReader.ItemWidget> catalog = reader.catalogItems(screen, build);

		final Map<Integer, Integer> current = new HashMap<>();
		for (SetupReader.ItemWidget iw : worn)
		{
			current.merge(iw.itemId, iw.quantity, Integer::sum);
		}
		for (SetupReader.ItemWidget iw : inventory)
		{
			current.merge(iw.itemId, iw.quantity, Integer::sum);
		}

		final String currentSpellbook = reader.spellbookLabel(screen, build);
		final LoadoutDiff diff = LoadoutDiff.compute(active.bag(), current, active.getSpellbook(), currentSpellbook);

		g.setStroke(STROKE);

		// To add: green outline over the whole option + count (only when >1), clipped to list.
		// While the catalog is filtered to just the loadout's items the outline is redundant
		// (every visible row already belongs to the loadout) and only clutters the list, so
		// suppress it there and keep the count alone.
		final boolean filtered = manager.isFilterOn();
		final Set<Integer> located = new HashSet<>();
		final Widget list = client.getWidget(screen.itemsList[build]);
		final Shape oldClip = g.getClip();
		if (list != null && !list.isHidden() && list.getBounds() != null)
		{
			g.setClip(list.getBounds());
		}
		for (SetupReader.ItemWidget row : catalog)
		{
			final int need = diff.needFor(row.itemId);
			if (need > 0 && row.widget != null && !row.widget.isHidden())
			{
				located.add(row.itemId);
				final Rectangle rowBounds = row.widget.getBounds();
				if (rowBounds == null)
				{
					continue;
				}
				if (!filtered)
				{
					final Rectangle bounds = optionBounds(row.widget);
					if (bounds != null)
					{
						g.setColor(ADD_COLOR);
						g.draw(bounds);
					}
				}
				if (need > 1)
				{
					drawCount(g, rowBounds, need);
				}
			}
		}
		g.setClip(oldClip);

		// Excess / unwanted: red outline only over the surplus that must be discarded to match
		// the loadout (wants 3 brews, setup has 5 -> mark just the last 2), not every copy. The
		// diff's per-item excess count is the budget. Inventory is spent first, walked bottom-up
		// so the trailing slots are marked, then worn — an equipped item is kept over a bag spare.
		// Ammo (bolts/arrows/darts) is never flagged as inventory excess: the equipped and
		// inventory forms report different item ids, so a stack sitting in the bag reads as
		// unwanted even though equipping it satisfies the loadout (see ADR-0002 / DESIGN.md
		// "variant surprises"). Suppress the red mark rather than confuse the player.
		final Map<Integer, Integer> remaining = new HashMap<>(diff.excess());
		final List<SetupReader.ItemWidget> orderedInv = new ArrayList<>(inventory);
		orderedInv.removeIf(iw -> isAmmo(iw.itemId));
		orderedInv.sort(Comparator.comparingInt(LoadoutOverlay::rowY).thenComparingInt(LoadoutOverlay::rowX));
		markExcess(g, orderedInv, remaining);
		markExcess(g, worn, remaining);

		// Spellbook differs.
		if (diff.spellbookMismatch())
		{
			outline(g, reader.spellbookWidget(screen, build), EXCESS_COLOR);
		}

		// Needed items with no catalog row to click (e.g. not available for this build).
		int unlocatable = 0;
		for (int itemId : diff.toAdd().keySet())
		{
			if (!located.contains(itemId))
			{
				unlocatable++;
			}
		}
		lastUnlocatable = unlocatable;
		lastUnlocatableActiveId = active.getId();

		// Only auto-clear once the player has actually worked toward the loadout: loading
		// an already-matching loadout (e.g. the one just saved from this setup) stays armed
		// rather than vanishing instantly.
		if (!diff.isFullMatch())
		{
			sawUnmatched = true;
		}
		else if (sawUnmatched)
		{
			manager.clearActive();
			matchConfirmUntil = System.currentTimeMillis() + MATCH_CONFIRM_MS;
			lastUnlocatable = 0;
			armedId = null;
			sawUnmatched = false;
		}

		return null;
	}

	/**
	 * Outlines only the last {@code remaining[itemId]} copies of each excess item — the exact
	 * surplus over the loadout — walking the list from the end so the trailing slots are marked
	 * and drawing the budget down by each widget's stack size (so one full stack can cover it).
	 */
	private void markExcess(Graphics2D g, List<SetupReader.ItemWidget> items, Map<Integer, Integer> remaining)
	{
		for (int i = items.size() - 1; i >= 0; i--)
		{
			final SetupReader.ItemWidget iw = items.get(i);
			final int left = remaining.getOrDefault(iw.itemId, 0);
			if (left <= 0)
			{
				continue;
			}
			outline(g, iw.widget, EXCESS_COLOR);
			remaining.put(iw.itemId, left - iw.quantity);
		}
	}

	/** Whether {@code itemId} equips to the ammo slot (bolts/arrows/darts/knives/etc.). */
	private boolean isAmmo(int itemId)
	{
		final ItemStats stats = itemManager.getItemStats(itemId);
		return stats != null && stats.getEquipment() != null
			&& stats.getEquipment().getSlot() == EquipmentInventorySlot.AMMO.getSlotIdx();
	}

	private static int rowY(SetupReader.ItemWidget iw)
	{
		final Rectangle b = iw.widget == null ? null : iw.widget.getBounds();
		return b == null ? Integer.MAX_VALUE : b.y;
	}

	private static int rowX(SetupReader.ItemWidget iw)
	{
		final Rectangle b = iw.widget == null ? null : iw.widget.getBounds();
		return b == null ? Integer.MAX_VALUE : b.x;
	}

	private void outline(Graphics2D g, Widget widget, Color color)
	{
		if (widget == null || widget.isHidden())
		{
			return;
		}
		final Rectangle b = widget.getBounds();
		if (b != null)
		{
			g.setColor(color);
			g.draw(b);
		}
	}

	/**
	 * Bounds of a full catalog option: the item icon unioned with the same-row sibling
	 * widgets (the item name text). Falls back to the row-container parent when that is
	 * itself the option, or the icon alone if neither is available.
	 */
	private Rectangle optionBounds(Widget icon)
	{
		final Rectangle ib = icon.getBounds();
		if (ib == null)
		{
			return null;
		}

		final Widget parent = icon.getParent();
		if (parent == null)
		{
			return ib;
		}

		final Rectangle pb = parent.getBounds();
		if (pb != null && pb.width >= ib.width && pb.height <= ib.height * 2 + 6)
		{
			return pb; // the parent is the option row itself
		}

		Rectangle r = new Rectangle(ib);
		r = unionRow(r, parent.getDynamicChildren(), ib);
		r = unionRow(r, parent.getChildren(), ib);
		return r;
	}

	private Rectangle unionRow(Rectangle r, Widget[] kids, Rectangle band)
	{
		if (kids != null)
		{
			for (Widget k : kids)
			{
				if (k == null || k.isHidden())
				{
					continue;
				}
				final Rectangle b = k.getBounds();
				if (b == null)
				{
					continue;
				}
				// Require a majority vertical overlap so only true same-row siblings merge.
				// A bare 1px overlap (e.g. an adjacent row shifted mid-scroll) must not
				// stretch the highlight across two options.
				final int overlap = Math.min(b.y + b.height, band.y + band.height) - Math.max(b.y, band.y);
				if (overlap * 2 >= Math.min(band.height, b.height))
				{
					r = r.union(b);
				}
			}
		}
		return r;
	}

	private void drawCount(Graphics2D g, Rectangle bounds, int n)
	{
		final String t = Integer.toString(n);
		g.setFont(COUNT_FONT);
		final int tw = g.getFontMetrics().stringWidth(t);
		final int x = bounds.x + bounds.width - tw - 1;
		final int y = bounds.y + bounds.height - 1;

		g.setColor(Color.BLACK);
		g.drawString(t, x + 1, y + 1);
		g.setColor(ADD_COLOR);
		g.drawString(t, x, y);
	}

	private void drawMatchedConfirmation(Graphics2D g, ArenaWidgets.Screen screen)
	{
		final Widget root = client.getWidget(screen.universe);
		if (root == null || root.isHidden() || root.getBounds() == null)
		{
			return;
		}
		final Rectangle b = root.getBounds();
		final String t = "Loadout matched";
		g.setFont(COUNT_FONT);
		final int tw = g.getFontMetrics().stringWidth(t);
		final int checkW = 8;
		final int gap = 3;
		final int x = b.x + (b.width - (checkW + gap + tw)) / 2;
		final int y = b.y + 14;

		drawCheck(g, x, y, checkW);

		final int tx = x + checkW + gap;
		g.setColor(Color.BLACK);
		g.drawString(t, tx + 1, y + 1);
		g.setColor(ADD_COLOR);
		g.drawString(t, tx, y);
	}

	/** Vector checkmark (the RuneScape font has no ✓ glyph), green with a black shadow. */
	private void drawCheck(Graphics2D g, int x, int baseline, int size)
	{
		final Object oldAa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		final Stroke oldStroke = g.getStroke();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));

		final int[] xs = {x, x + size / 3, x + size};
		final int[] ys = {baseline - 3, baseline, baseline - size};

		g.setColor(Color.BLACK);
		g.drawPolyline(new int[]{xs[0] + 1, xs[1] + 1, xs[2] + 1}, new int[]{ys[0] + 1, ys[1] + 1, ys[2] + 1}, 3);
		g.setColor(ADD_COLOR);
		g.drawPolyline(xs, ys, 3);

		g.setStroke(oldStroke);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
			oldAa == null ? RenderingHints.VALUE_ANTIALIAS_DEFAULT : oldAa);
	}
}

package com.pvparena;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics2D;
import java.awt.GridBagLayout;
import java.awt.GridLayout;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.JMenuItem;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/**
 * Feature 3 — the Loadouts sidebar. Lists saved {@link Loadout}s in three fixed build
 * groups, a builder-gated "Save current setup" button, and per-entry actions. Pure
 * Swing on the EDT: it only reads cached state (never touches the client directly) and
 * delegates client-coupled work to {@link Actions}.
 */
@Slf4j
class LoadoutPanel extends PluginPanel
{
	private static final Color ACTIVE_BG = new Color(64, 54, 24);
	private static final Color ICON_FG = new Color(200, 200, 200);

	/** Square canvas (px) shared by both control icons so the buttons match. */
	private static final int ICON_SIZE = 8;
	/** Fixed square size for the stop/options buttons. */
	private static final Dimension CONTROL_BTN_SIZE = new Dimension(18, 18);

	/** A filled square ("stop comparing"). */
	private static final Icon STOP_ICON = stopIcon();
	/** A horizontal ellipsis ("loadout options"). */
	private static final Icon MENU_ICON = menuIcon();
	/** A funnel: filled = filter engaged, outline = full catalog shown. */
	private static final Icon FILTER_ON_ICON = filterIcon(true);
	private static final Icon FILTER_OFF_ICON = filterIcon(false);

	/** Callbacks into the plugin for anything that needs the client thread or a dialog. */
	interface Actions
	{
		boolean isBuilderOpen();

		void saveCurrentSetup();

		void load(Loadout loadout);

		void stop();

		boolean isFilterOn();

		void toggleFilter();

		void updateFromSetup(Loadout loadout);

		void rename(Loadout loadout);

		void delete(Loadout loadout);

		/** Export: copy this loadout to the clipboard as a Loadout code. */
		void copyCode(Loadout loadout);

		/** Import: mint a loadout from a Loadout code on the clipboard. */
		void importCode();

		int unlocatableCount(Loadout active);
	}

	private final LoadoutManager manager;
	private final Actions actions;

	private final JButton saveButton = new JButton("Save current setup");
	/** Always enabled (unlike {@code saveButton}); import touches only clipboard + config. */
	private final JButton importButton = new JButton("Import loadout code");
	private final JPanel groups = new JPanel();
	private final Map<Integer, Boolean> collapsed = new HashMap<>();

	LoadoutPanel(LoadoutManager manager, Actions actions)
	{
		this.manager = manager;
		this.actions = actions;

		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		saveButton.addActionListener(e -> actions.saveCurrentSetup());
		importButton.setToolTipText("Create a loadout from a code on your clipboard");
		importButton.addActionListener(e -> actions.importCode());

		final JPanel top = new JPanel(new GridLayout(0, 1, 0, 4));
		top.add(saveButton);
		top.add(importButton);
		add(top, BorderLayout.NORTH);

		groups.setLayout(new BoxLayout(groups, BoxLayout.Y_AXIS));
		add(groups, BorderLayout.CENTER);

		rebuild();
	}

	/** Rebuilds the whole list from current state. Safe to call from any thread. */
	void rebuild()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::rebuild);
			return;
		}

		try
		{
			final boolean builderOpen = actions.isBuilderOpen();
			saveButton.setEnabled(builderOpen);
			saveButton.setToolTipText(builderOpen
				? "Save the build you're currently editing as a loadout"
				: "Open the arena setup screen to save");

			groups.removeAll();
			for (Build build : Build.values())
			{
				groups.add(buildSection(build));
				groups.add(javax.swing.Box.createVerticalStrut(6));
			}
			groups.revalidate();
			groups.repaint();
		}
		catch (Exception e)
		{
			log.warn("Loadout panel rebuild failed", e);
		}
	}

	private JPanel buildSection(Build build)
	{
		final List<Loadout> loadouts = manager.forBuild(build.getValue());
		final boolean isCollapsed = collapsed.getOrDefault(build.getValue(), false);

		final JPanel section = new JPanel(new BorderLayout());
		section.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));

		final JButton header = new JButton((isCollapsed ? "+ " : "- ") + build.getLabel() + "  (" + loadouts.size() + ")");
		header.setHorizontalAlignment(SwingConstants.LEFT);
		header.setFocusPainted(false);
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.addActionListener(e ->
		{
			collapsed.put(build.getValue(), !isCollapsed);
			rebuild();
		});
		section.add(header, BorderLayout.NORTH);

		if (!isCollapsed)
		{
			final JPanel body = new JPanel();
			body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
			body.setBorder(BorderFactory.createEmptyBorder(4, 2, 4, 2));

			if (loadouts.isEmpty())
			{
				final JLabel empty = new JLabel("No loadouts yet");
				empty.setForeground(Color.GRAY);
				empty.setBorder(BorderFactory.createEmptyBorder(2, 4, 2, 4));
				body.add(empty);
			}
			else
			{
				for (Loadout l : loadouts)
				{
					body.add(entryRow(l));
					body.add(javax.swing.Box.createVerticalStrut(3));
				}
			}
			section.add(body, BorderLayout.CENTER);
		}

		return section;
	}

	private JPanel entryRow(Loadout loadout)
	{
		final boolean isActive = manager.isActive(loadout);

		final JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 4));
		row.setBackground(isActive ? ACTIVE_BG : ColorScheme.DARKER_GRAY_COLOR);
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 44));

		final JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setOpaque(false);

		final JLabel name = new JLabel(loadout.getName() == null ? "(unnamed)" : loadout.getName());
		text.add(name);

		final StringBuilder sub = new StringBuilder();
		final String book = shortSpellbook(loadout.getSpellbook());
		if (book != null)
		{
			sub.append(book);
		}
		if (isActive)
		{
			final int missing = actions.unlocatableCount(loadout);
			if (missing > 0)
			{
				sub.append(sub.length() > 0 ? "  " : "").append(missing).append(" not in catalog");
			}
		}
		if (sub.length() > 0)
		{
			final JLabel tag = new JLabel(sub.toString());
			tag.setForeground(Color.GRAY);
			text.add(tag);
		}
		row.add(text, BorderLayout.CENTER);

		final JPanel controls = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
		controls.setOpaque(false);
		if (isActive)
		{
			final boolean filterOn = actions.isFilterOn();
			final JButton filter = controlButton(filterOn ? FILTER_ON_ICON : FILTER_OFF_ICON,
				filterOn
					? "Showing only this loadout's items - click to show the full catalog"
					: "Filter the catalog to only this loadout's items");
			filter.addActionListener(e -> actions.toggleFilter());
			controls.add(filter);

			final JButton stop = controlButton(STOP_ICON, "Stop comparing");
			stop.addActionListener(e -> actions.stop());
			controls.add(stop);
		}
		final JButton menu = controlButton(MENU_ICON, "Loadout options");
		menu.addActionListener(e -> showMenu(loadout, menu));
		controls.add(menu);

		// Wrap in GridBag so the fixed-height controls center vertically in the row.
		final JPanel controlsWrap = new JPanel(new GridBagLayout());
		controlsWrap.setOpaque(false);
		controlsWrap.add(controls);
		row.add(controlsWrap, BorderLayout.EAST);

		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				actions.load(loadout);
			}
		});

		return row;
	}

	private void showMenu(Loadout loadout, Component anchor)
	{
		final JPopupMenu popup = new JPopupMenu();

		final JMenuItem rename = new JMenuItem("Rename");
		rename.addActionListener(e -> actions.rename(loadout));
		popup.add(rename);

		final JMenuItem update = new JMenuItem("Update from current setup");
		update.setEnabled(actions.isBuilderOpen());
		update.addActionListener(e -> actions.updateFromSetup(loadout));
		popup.add(update);

		final JMenuItem copyCode = new JMenuItem("Copy loadout code");
		copyCode.addActionListener(e -> actions.copyCode(loadout));
		popup.add(copyCode);

		final JMenuItem delete = new JMenuItem("Delete");
		delete.addActionListener(e -> actions.delete(loadout));
		popup.add(delete);

		popup.show(anchor, 0, anchor.getHeight());
	}

	private static String shortSpellbook(String label)
	{
		if (label == null || label.trim().isEmpty())
		{
			return null;
		}
		final String t = label.trim();
		final int space = t.indexOf(' ');
		return space > 0 ? t.substring(0, space) : t;
	}

	/** A fixed-size square icon button so the stop and options controls match exactly. */
	private static JButton controlButton(Icon icon, String tooltip)
	{
		final JButton b = new JButton(icon);
		b.setToolTipText(tooltip);
		b.setMargin(new java.awt.Insets(0, 0, 0, 0));
		b.setPreferredSize(CONTROL_BTN_SIZE);
		b.setMinimumSize(CONTROL_BTN_SIZE);
		b.setMaximumSize(CONTROL_BTN_SIZE);
		return b;
	}

	private static BufferedImage iconCanvas()
	{
		return new BufferedImage(ICON_SIZE, ICON_SIZE, BufferedImage.TYPE_INT_ARGB);
	}

	private static Icon stopIcon()
	{
		final int side = 6;
		final int off = (ICON_SIZE - side) / 2;
		final BufferedImage img = iconCanvas();
		final Graphics2D g = img.createGraphics();
		g.setColor(ICON_FG);
		g.fillRect(off, off, side, side);
		g.dispose();
		return new ImageIcon(img);
	}

	private static Icon filterIcon(boolean on)
	{
		// A funnel: wide mouth at top tapering to a short stem.
		final int[] xs = {0, ICON_SIZE, ICON_SIZE - 3, ICON_SIZE - 3, 3, 3};
		final int[] ys = {1, 1, 4, ICON_SIZE, ICON_SIZE, 4};
		final Polygon funnel = new Polygon(xs, ys, xs.length);
		final BufferedImage img = iconCanvas();
		final Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(on ? ICON_FG : new Color(110, 110, 110));
		if (on)
		{
			g.fill(funnel);
		}
		else
		{
			g.draw(funnel);
		}
		g.dispose();
		return new ImageIcon(img);
	}

	private static Icon menuIcon()
	{
		final int dot = 2;
		final int gap = 1;
		final int totalW = dot * 3 + gap * 2;
		final int x0 = (ICON_SIZE - totalW) / 2;
		final int y = (ICON_SIZE - dot) / 2;
		final BufferedImage img = iconCanvas();
		final Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(ICON_FG);
		for (int i = 0; i < 3; i++)
		{
			g.fillOval(x0 + i * (dot + gap), y, dot, dot);
		}
		g.dispose();
		return new ImageIcon(img);
	}
}

package com.pvparena;

import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import javax.inject.Singleton;

/**
 * Optimistic-add ledger for the catalog filter (Feature 3). The owned-inventory widget
 * ({@code _NINVENTORY}) that {@link SetupReader#currentBag} reads lags an item add by
 * ~1 game tick (~600ms), so a filtered "to add" row lingers during the window and a fast
 * second click double-adds. This credits each click immediately, letting the row vanish on
 * the next {@link net.runelite.api.events.ClientTick} (~1 frame) instead.
 *
 * <p>Pure and unit-tested like {@link LoadoutDiff} — no {@link net.runelite.api.Client}
 * dependency (the game tick is passed in, not read). Holds three parallel maps keyed by
 * item id:
 * <ul>
 *   <li>{@code pending} — clicks credited but not yet seen in the real read.</li>
 *   <li>{@code baseline} — the real count captured the first tick a prediction was live,
 *       so reconciliation diffs against where the stack started, not against zero.</li>
 *   <li>{@code recordedTick} — the game tick of the most recent click, for the TTL backstop.</li>
 * </ul>
 *
 * <p>Reconciliation is baseline-diff: once the real read has grown by at least the predicted
 * amount since its baseline the prediction retires; until then the shortfall is added back on
 * top of the live read. A prediction whose add never lands in the read (the item was removed
 * again by <em>any</em> path — Discard, wipe, trash, drag) can't be reconciled by an add-only
 * diff, so a {@value #TTL_TICKS}-game-tick TTL past the last click retires it as a backstop;
 * the row then returns instead of sticking forever. Retirement is not inferred from the read
 * moving <em>down</em> — that read dips transiently while the grid rebuilds during rapid
 * filling, and dropping a live prediction there re-opens the double-add. Not thread-safe — all
 * access is on the client thread (the tick + click handlers), same as {@link CatalogFilter}.
 */
@Singleton
class PendingAdds
{
	/**
	 * Game ticks a prediction survives past its last click before the TTL backstop retires it.
	 * Must exceed the ~1-tick read lag the prediction bridges (else the double-add window reopens);
	 * small so a removed row returns quickly.
	 */
	private static final int TTL_TICKS = 2;

	/** itemId -&gt; clicks credited but not yet reflected in the real read. */
	private final Map<Integer, Integer> pending = new HashMap<>();
	/** itemId -&gt; real count when the prediction went 0-&gt;1 (the diff baseline). */
	private final Map<Integer, Integer> baseline = new HashMap<>();
	/** itemId -&gt; game tick of the most recent click, for the TTL backstop. */
	private final Map<Integer, Integer> recordedTick = new HashMap<>();

	/**
	 * Credits one optimistic add of {@code itemId} (a single {@code Add} catalog click) at game
	 * tick {@code tick}, refreshing its TTL so an actively-clicked stack never expires mid-fill.
	 */
	void record(int itemId, int tick)
	{
		pending.merge(itemId, 1, Integer::sum);
		recordedTick.put(itemId, tick);
	}

	/**
	 * Reconciles predictions against {@code currentBag} (the live worn+inventory read) at game
	 * tick {@code tick} and returns a fresh bag with any surviving predictions merged on top.
	 * Never mutates the input. Retires a prediction once the real read has grown by at least the
	 * predicted amount since its baseline, or {@value #TTL_TICKS} ticks past its last click if the
	 * read never catches up (the item was removed again).
	 */
	Map<Integer, Integer> effectiveBag(Map<Integer, Integer> currentBag, int tick)
	{
		final Map<Integer, Integer> result = new HashMap<>(currentBag);

		final Iterator<Map.Entry<Integer, Integer>> it = pending.entrySet().iterator();
		while (it.hasNext())
		{
			final Map.Entry<Integer, Integer> e = it.next();
			final int itemId = e.getKey();
			final int predicted = e.getValue();

			// Backstop: the add never landed within the TTL, so the item was removed again by a
			// path the add-only diff can't see (Discard/wipe/trash/drag). Give up on the read
			// catching up and drop the prediction so the row returns.
			if (tick - recordedTick.getOrDefault(itemId, tick) >= TTL_TICKS)
			{
				it.remove();
				baseline.remove(itemId);
				recordedTick.remove(itemId);
				continue;
			}

			// First tick a prediction is live, pin the baseline to the (pre-add) real count.
			final int base = baseline.computeIfAbsent(itemId, k -> currentBag.getOrDefault(k, 0));
			final int gained = currentBag.getOrDefault(itemId, 0) - base;
			final int surviving = predicted - gained;

			if (surviving > 0)
			{
				result.merge(itemId, surviving, Integer::sum);
			}
			else
			{
				// Real read caught up: drop the prediction and its baseline.
				it.remove();
				baseline.remove(itemId);
				recordedTick.remove(itemId);
			}
		}
		return result;
	}

	/** Forgets every prediction; called wherever the catalog filter is cleared. */
	void clear()
	{
		pending.clear();
		baseline.clear();
		recordedTick.clear();
	}
}

package com.pvparena;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(PvpArenaConfig.GROUP)
public interface PvpArenaConfig extends Config
{
	String GROUP = "pvparena";

	@ConfigItem(
		keyName = "shiftClickDelete",
		name = "Shift-click discard",
		description = "On loadout items that left-click discard, swap so left-click examines and Shift + left-click discards. Right-click is unchanged."
	)
	default boolean shiftClickDelete()
	{
		return true;
	}

	@ConfigItem(
		keyName = "spellbookMismatch",
		name = "Highlight spellbook mismatch",
		description = "On the unranked duel screen, outline your spellbook, the opponent's spellbook, and the confirm button when the two spellbooks differ."
	)
	default boolean spellbookMismatch()
	{
		return true;
	}

	@ConfigItem(
		keyName = "loadouts",
		name = "Loadouts",
		description = "Save named setups (worn, inventory, spellbook) grouped by build, and load one to highlight what to add or remove. Sidebar panel shows on PvP Arena worlds."
	)
	default boolean loadouts()
	{
		return true;
	}
}

package com.pvparena;

import com.google.inject.Provides;
import java.awt.Toolkit;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WorldType;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "PvP Arena",
	description = "Quality-of-life utilities for dueling on PvP Arena worlds: shift-click discard, spellbook-mismatch warnings, and loadouts.",
	tags = {"pvp", "arena", "duel", "spellbook", "loadout", "discard", "qol", "pk", "nh", "veng"}
)
public class PvpArenaPlugin extends Plugin implements LoadoutPanel.Actions
{
	/** Left-click add-one option on an arena catalog row (confirmed in-game 2026-08-11: "Add", a CC_OP). */
	private static final String ADD_ONE = "Add";
	/** Arena supply grid capacity for the optimistic-add full check (VERIFY in-game: 28 slots). */
	private static final int INVENTORY_CAPACITY = 28;

	@Inject
	private Client client;

	@Inject
	private PvpArenaConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SpellbookMismatchOverlay spellbookMismatchOverlay;

	@Inject
	private ShiftClickDeleteHandler shiftClickDeleteHandler;

	@Inject
	private LoadoutOverlay loadoutOverlay;

	@Inject
	private LoadoutManager loadoutManager;

	@Inject
	private LoadoutCodec loadoutCodec;

	@Inject
	private SetupReader setupReader;

	@Inject
	private CatalogFilter catalogFilter;

	@Inject
	private PendingAdds pendingAdds;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ClientThread clientThread;

	private LoadoutPanel panel;
	private NavigationButton navButton;
	private boolean navAdded;

	/** Cached so the Swing panel can read it without touching the client thread. */
	private volatile boolean builderOpen;
	private String lastActiveId;
	private int lastUnrankedProgress;

	/** Build + loadout the current optimistic predictions belong to; a change invalidates them. */
	private int pendingBuild = -1;
	private String pendingActiveId;

	/**
	 * Stable {@code hotspot dense index (param0) -> catalog item id}, so a rapid second click on a
	 * row can still be identified while that row is mid-repack and live resolution fails. Keyed only
	 * by param0 because the catalog's item set is constant per list; invalidated when the list
	 * component ({@link #lastCatalogList}) changes (build / screen switch).
	 */
	private final Map<Integer, Integer> catalogItemByHotspot = new HashMap<>();
	private int lastCatalogList = -1;

	@Provides
	PvpArenaConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PvpArenaConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(spellbookMismatchOverlay);
		overlayManager.add(loadoutOverlay);

		panel = new LoadoutPanel(loadoutManager, this);
		navButton = NavigationButton.builder()
			.tooltip("PvP Arena loadouts")
			.icon(navIcon())
			.priority(7)
			.panel(panel)
			.build();

		clientThread.invoke(this::updateNav);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(spellbookMismatchOverlay);
		overlayManager.remove(loadoutOverlay);
		removeNav();
		clientThread.invoke(this::clearFilter);
		loadoutManager.clearActive();
		panel = null;
		builderOpen = false;
		lastActiveId = null;
	}

	/**
	 * Shared world-layer gate. Every feature additionally checks that its own target
	 * interface is loaded before acting (see DESIGN.md "Activation gate").
	 */
	public boolean inPvpArena()
	{
		return client.getWorldType().contains(WorldType.PVP_ARENA);
	}

	/**
	 * Feature 1 (shift-click discard) hooks the left-click menu, which only resolves
	 * while the right-click menu is closed. {@link PostMenuSort} fires in exactly that
	 * window, so a deliberate right-click Discard is never touched.
	 */
	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		if (!config.shiftClickDelete() || !inPvpArena())
		{
			return;
		}

		shiftClickDeleteHandler.applyLeftClickSwap();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		final boolean prevOpen = builderOpen;
		final boolean open = config.loadouts() && inPvpArena() && setupReader.isBuilderOpen();

		if (!prevOpen && open)
		{
			// Fresh builder session: forget any stale duel-progress reading.
			lastUnrankedProgress = 0;
			logBuilderContents();
		}

		// Duel-begin heuristic (VERIFY in-game): the builder closing while an unranked
		// confirm was in progress means the fight is starting -> drop the armed loadout.
		// A plain browse-and-close (progress 0) keeps it armed, per the load lifecycle.
		if (prevOpen && !open && lastUnrankedProgress > 0)
		{
			loadoutManager.clearActive();
		}

		final String activeId = idOf(loadoutManager.getActive());
		if (open != prevOpen || !Objects.equals(activeId, lastActiveId))
		{
			refreshPanel();
		}
		builderOpen = open;
		lastActiveId = activeId;

		updateNav();
	}

	/**
	 * Drives the catalog filter (Feature 3). Polled every client tick because the game
	 * rebuilds the catalog on its own (item add/remove, build switch) and {@link CatalogFilter}
	 * must re-apply after each rebuild; it self-short-circuits when already filtered.
	 */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (!config.loadouts() || !inPvpArena())
		{
			clearFilter();
			return;
		}

		final ArenaWidgets.Screen s = setupReader.openScreen();
		final Loadout active = loadoutManager.getActive();
		if (s == null || active == null)
		{
			clearFilter();
			return;
		}

		final int build = setupReader.activeBuild(s);

		if (loadoutManager.isFilterOn())
		{
			// Predictions are scoped to one build + loadout; a switch to either makes them
			// meaningless (a different inventory / target), so drop them before reconciling.
			final String activeId = active.getId();
			if (build != pendingBuild || !Objects.equals(activeId, pendingActiveId))
			{
				pendingAdds.clear();
				pendingBuild = build;
				pendingActiveId = activeId;
			}

			// Keep only rows the loadout still highlights (need > 0), same set as the green
			// to-add outline; the catalog shrinks as the player adds items. Credit clicks
			// optimistically so a just-added row clears this tick, not a game tick later.
			final Map<Integer, Integer> current = pendingAdds.effectiveBag(setupReader.currentBag(s, build), client.getTickCount());
			final LoadoutDiff diff = LoadoutDiff.compute(active.bag(), current,
				active.getSpellbook(), setupReader.spellbookLabel(s, build));
			catalogFilter.maintain(s, build, filterOrder(active, diff.toAdd().keySet()));
		}
		else
		{
			clearFilter();
		}
	}

	/**
	 * Display order (top to bottom) for the filtered catalog: equipable items first by
	 * equipment slot (head to ammo), then everything else by target quantity ascending.
	 * "Equipable" is by item stats, so equipable items stored in the loadout's inventory
	 * (switches) sort with the worn gear, not the consumables. Ties broken by item id.
	 */
	private List<Integer> filterOrder(Loadout l, Set<Integer> needed)
	{
		final Map<Integer, Integer> target = l.bag();
		final List<Integer> wearables = new ArrayList<>();
		final List<Integer> rest = new ArrayList<>();
		for (int id : needed)
		{
			(isEquipable(id) ? wearables : rest).add(id);
		}
		wearables.sort(Comparator.comparingInt((Integer id) -> equipSlot(id)).thenComparingInt(id -> id));
		rest.sort(Comparator.comparingInt((Integer id) -> target.getOrDefault(id, 1)).thenComparingInt(id -> id));

		final List<Integer> order = new ArrayList<>(wearables.size() + rest.size());
		order.addAll(wearables);
		order.addAll(rest);
		return order;
	}

	/** Restores the catalog and forgets optimistic predictions together (they share a lifecycle). */
	private void clearFilter()
	{
		catalogFilter.clear();
		pendingAdds.clear();
	}

	/** Whether the shown build's supply grid is full, so an {@code Add} click can't land. */
	private boolean inventoryFull(ArenaWidgets.Screen s, int build)
	{
		return setupReader.inventoryItems(s, build).size() >= INVENTORY_CAPACITY;
	}

	private boolean isEquipable(int itemId)
	{
		final ItemStats stats = itemManager.getItemStats(itemId);
		return stats != null && stats.isEquipable();
	}

	/** Equipment slot for ordering wearables head-to-toe; large for non-equipment. */
	private int equipSlot(int itemId)
	{
		final ItemStats stats = itemManager.getItemStats(itemId);
		if (stats == null || stats.getEquipment() == null)
		{
			return Integer.MAX_VALUE;
		}
		return stats.getEquipment().getSlot();
	}

	/**
	 * Disengage the catalog filter when the player clicks the catalog search ({@code _NSEEK})
	 * button, so the native search isn't fought. {@link #onClientTick} restores the full
	 * catalog on the next tick.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!config.loadouts() || !loadoutManager.isFilterOn())
		{
			return;
		}
		final Widget w = event.getWidget();
		if (ArenaWidgets.isSeekWidget(event.getParam1())
			|| (w != null && ArenaWidgets.isSeekWidget(w.getId())))
		{
			loadoutManager.setFilterOn(false);
			refreshPanel();
			return;
		}

		// Optimistic catalog add (Feature 3): an "Add" click won't reach the lagging
		// _NINVENTORY read for ~1 game tick. Credit it now so the filtered row clears on the
		// next ClientTick; and when the loadout target is already met (live read plus clicks
		// still in flight), consume the click. The filter only hides the row a frame later, so
		// consuming is what actually stops a fast second click on a not-yet-hidden row from
		// double-adding. Skip when the supply grid is full, where the add can't land anyway.
		// The op is a bespoke CC_OP whose menu-entry item id is unset, so resolve the row's item
		// off the list widget (confirmed in-game 2026-08-11; see CatalogFilter#clickedRowItemId).
		if (inPvpArena() && ADD_ONE.equals(event.getMenuOption()))
		{
			final int p0 = event.getParam0();
			final int p1 = event.getParam1();
			if (p1 != lastCatalogList)
			{
				catalogItemByHotspot.clear(); // catalog list rebuilt/switched: hotspot->item map is stale
				lastCatalogList = p1;
			}

			int itemId = catalogFilter.clickedRowItemId(p1, p0);
			if (itemId > 0)
			{
				catalogItemByHotspot.put(p0, itemId);
			}
			else
			{
				// The just-clicked row is mid-repack (its icon has moved/hidden) so live resolution
				// fails; reuse the stable id cached from an earlier click on this same hotspot, so a
				// rapid second click on a now-satisfied row is still recognised and consumed.
				itemId = catalogItemByHotspot.getOrDefault(p0, -1);
			}
			if (itemId <= 0)
			{
				return; // couldn't resolve the clicked row's item: nothing to credit or block
			}
			final ArenaWidgets.Screen s = setupReader.openScreen();
			final Loadout active = loadoutManager.getActive();
			if (s == null || active == null)
			{
				return;
			}
			final int build = setupReader.activeBuild(s);
			if (inventoryFull(s, build))
			{
				return; // add can't land: nothing to credit, no excess to block
			}

			final int want = active.bag().getOrDefault(itemId, 0);
			// effectiveBag reconciles first, so a game tick landing since the last ClientTick
			// (real grew, prediction not yet retired) can't double-count into a false block.
			final int have = pendingAdds.effectiveBag(setupReader.currentBag(s, build), client.getTickCount())
				.getOrDefault(itemId, 0);
			if (want > 0 && have >= want)
			{
				event.consume(); // target already satisfied — block the duplicate add
				return;
			}
			pendingAdds.record(itemId, client.getTickCount());
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() == VarbitID.PVPA_UNRANKEDDUEL_TRANSMIT_PROGRESS)
		{
			lastUnrankedProgress = event.getValue();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			loadoutManager.clearActive();
			pendingAdds.clear(); // client thread; drop stale predictions across the hop
			catalogItemByHotspot.clear();
			lastCatalogList = -1;
		}
		updateNav();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!PvpArenaConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if (!config.loadouts())
		{
			loadoutManager.clearActive();
		}
		clientThread.invoke(this::updateNav);
		refreshPanel();
	}

	// --- LoadoutPanel.Actions -------------------------------------------------------

	@Override
	public boolean isBuilderOpen()
	{
		return builderOpen;
	}

	@Override
	public void saveCurrentSetup()
	{
		clientThread.invoke(() ->
		{
			final Loadout snapshot = setupReader.readSnapshot();
			SwingUtilities.invokeLater(() -> finishSave(snapshot));
		});
	}

	private void finishSave(Loadout snapshot)
	{
		if (snapshot == null)
		{
			JOptionPane.showMessageDialog(panel, "Open the arena setup screen first.");
			return;
		}

		final String def = Build.labelFor(snapshot.getBuild()) + " loadout";
		final Object input = JOptionPane.showInputDialog(panel, "Loadout name:", "Save loadout",
			JOptionPane.PLAIN_MESSAGE, null, null, def);
		if (input == null)
		{
			return;
		}

		String name = input.toString().trim();
		if (name.isEmpty())
		{
			name = def;
		}
		loadoutManager.add(snapshot, name);
		refreshPanel();
	}

	@Override
	public void load(Loadout loadout)
	{
		loadoutManager.setActive(loadout);
		refreshPanel();
	}

	@Override
	public void stop()
	{
		loadoutManager.clearActive();
		clientThread.invoke(this::clearFilter);
		refreshPanel();
	}

	@Override
	public boolean isFilterOn()
	{
		return loadoutManager.isFilterOn();
	}

	@Override
	public void toggleFilter()
	{
		loadoutManager.setFilterOn(!loadoutManager.isFilterOn());
		refreshPanel(); // onClientTick applies/clears on the client thread next tick
	}

	@Override
	public void updateFromSetup(Loadout loadout)
	{
		final String id = loadout.getId();
		clientThread.invoke(() ->
		{
			final Loadout snapshot = setupReader.readSnapshot();
			SwingUtilities.invokeLater(() ->
			{
				if (snapshot == null)
				{
					JOptionPane.showMessageDialog(panel, "Open the arena setup screen first.");
					return;
				}
				loadoutManager.update(id, snapshot);
				refreshPanel();
			});
		});
	}

	@Override
	public void rename(Loadout loadout)
	{
		final Object input = JOptionPane.showInputDialog(panel, "Loadout name:", "Rename loadout",
			JOptionPane.PLAIN_MESSAGE, null, null, loadout.getName());
		if (input == null)
		{
			return;
		}
		final String name = input.toString().trim();
		if (!name.isEmpty())
		{
			loadoutManager.rename(loadout.getId(), name);
			refreshPanel();
		}
	}

	@Override
	public void delete(Loadout loadout)
	{
		final int result = JOptionPane.showConfirmDialog(panel,
			"Delete \"" + loadout.getName() + "\"?", "Delete loadout", JOptionPane.YES_NO_OPTION);
		if (result == JOptionPane.YES_OPTION)
		{
			loadoutManager.delete(loadout.getId());
			refreshPanel();
		}
	}

	/**
	 * Export. Pure EDT: clipboard + config only, no client thread (unlike
	 * {@link #saveCurrentSetup}). Availability is gated only incidentally by panel
	 * visibility (PvP Arena worlds), see ADR-0004.
	 */
	@Override
	public void copyCode(Loadout loadout)
	{
		if (loadout == null)
		{
			return;
		}
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(
			new StringSelection(loadoutCodec.encode(loadout)), null);
		JOptionPane.showMessageDialog(panel,
			"Copied loadout code for \"" + loadout.getName() + "\" to your clipboard.",
			"Loadout code copied", JOptionPane.INFORMATION_MESSAGE);
	}

	/** Import. Reads the clipboard, decodes, and adds a fresh loadout in the encoded build. */
	@Override
	public void importCode()
	{
		final String raw = readClipboard();
		if (raw == null || raw.trim().isEmpty())
		{
			JOptionPane.showMessageDialog(panel,
				"Couldn't read a loadout code from your clipboard. Copy one and try again.",
				"Import loadout code", JOptionPane.WARNING_MESSAGE);
			return;
		}

		final Loadout decoded;
		try
		{
			decoded = loadoutCodec.decode(raw);
		}
		catch (LoadoutCodecException e)
		{
			JOptionPane.showMessageDialog(panel, importErrorMessage(e.getReason()),
				"Import loadout code", JOptionPane.ERROR_MESSAGE);
			return;
		}

		final String name = decoded.getName() == null || decoded.getName().trim().isEmpty()
			? Build.labelFor(decoded.getBuild()) + " loadout"
			: decoded.getName();
		loadoutManager.add(decoded, name);
		refreshPanel();
	}

	private String readClipboard()
	{
		try
		{
			final Object data = Toolkit.getDefaultToolkit().getSystemClipboard()
				.getData(DataFlavor.stringFlavor);
			return data == null ? null : data.toString();
		}
		catch (UnsupportedFlavorException | IOException | IllegalStateException e)
		{
			// Non-text clipboard, or the clipboard was busy: treat as nothing to import.
			log.debug("Clipboard read failed", e);
			return null;
		}
	}

	private static String importErrorMessage(LoadoutCodecException.Reason reason)
	{
		if (reason == LoadoutCodecException.Reason.NEWER_VERSION)
		{
			return "This loadout code was made with a newer version of the plugin. "
				+ "Update PvP Arena to import it.";
		}
		return "That doesn't look like a valid loadout code. Copy the full code "
			+ "(it starts with \"pvpa-loadout-\") and try again.";
	}

	@Override
	public int unlocatableCount(Loadout active)
	{
		if (active == null || active.getId() == null)
		{
			return 0;
		}
		return active.getId().equals(loadoutOverlay.getLastUnlocatableActiveId())
			? loadoutOverlay.getLastUnlocatable()
			: 0;
	}

	// --- helpers --------------------------------------------------------------------

	private void refreshPanel()
	{
		final LoadoutPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(p::rebuild);
		}
	}

	private void updateNav()
	{
		final boolean show = config.loadouts() && inPvpArena();
		if (show && !navAdded)
		{
			clientToolbar.addNavigation(navButton);
			navAdded = true;
			refreshPanel();
		}
		else if (!show && navAdded)
		{
			removeNav();
		}
	}

	private void removeNav()
	{
		if (navAdded && navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navAdded = false;
		}
	}

	private static String idOf(Loadout loadout)
	{
		return loadout == null ? null : loadout.getId();
	}

	/** Debug aid (VERIFY in-game): confirms the worn/inventory/catalog reads find items. */
	private void logBuilderContents()
	{
		if (!log.isDebugEnabled())
		{
			return;
		}
		final ArenaWidgets.Screen s = setupReader.openScreen();
		if (s == null)
		{
			return;
		}
		final int b = setupReader.activeBuild(s);
		log.debug("PvP Arena builder open: build={} worn={} inventory={} catalog={}",
			b, setupReader.wornItems(s, b).size(), setupReader.inventoryItems(s, b).size(),
			setupReader.catalogItems(s, b).size());
	}

	private static BufferedImage navIcon()
	{
		return ImageUtil.loadImageResource(PvpArenaPlugin.class, "icon.png");
	}
}

package com.pvparena;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

/**
 * Reads the live {@link Setup} (worn equipment, inventory supplies + quantities,
 * spellbook) from the {@link Setup builder} widgets — never from varbits (ADR-0001).
 * Used both to snapshot on save and to build the current bag for the load diff. All
 * reads are null-safe and degrade to empty when a guessed widget id is wrong.
 *
 * <p>The catalog and the owned inventory are separate areas. The catalog is the
 * {@code _NITEMS_LIST} widget (verified: "to add" highlights land on it). The owned
 * inventory grid's exact id is uncertain, so it is read by exclusion: every visible
 * item widget under the screen that is not in the catalog list or the worn slots.
 */
@Singleton
class SetupReader
{
	/** An item-bearing widget plus what it holds. {@code slot} is the equipment slot, or -1. */
	static final class ItemWidget
	{
		final int itemId;
		final int quantity;
		final int slot;
		final Widget widget;

		ItemWidget(int itemId, int quantity, int slot, Widget widget)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.slot = slot;
			this.widget = widget;
		}
	}

	private final Client client;

	@Inject
	SetupReader(Client client)
	{
		this.client = client;
	}

	/** The open builder screen, or null if neither is loaded/visible. */
	ArenaWidgets.Screen openScreen()
	{
		for (ArenaWidgets.Screen s : ArenaWidgets.SCREENS)
		{
			final Widget root = client.getWidget(s.universe);
			if (root != null && !root.isHidden())
			{
				return s;
			}
		}
		return null;
	}

	boolean isBuilderOpen()
	{
		return openScreen() != null;
	}

	/**
	 * Build (0/1/2) currently shown: the build whose {@code _NWORN} panel is visible.
	 * Falls back to {@code PVPA_TRANSMIT_BUILD} if none reads as visible.
	 */
	int activeBuild(ArenaWidgets.Screen s)
	{
		for (int b = 0; b < s.wornRoot.length; b++)
		{
			final Widget w = client.getWidget(s.wornRoot[b]);
			if (w != null && !w.isHidden())
			{
				return b;
			}
		}
		final int v = client.getVarbitValue(VarbitID.PVPA_TRANSMIT_BUILD);
		return (v >= 0 && v <= 2) ? v : 0;
	}

	List<ItemWidget> wornItems(ArenaWidgets.Screen s, int build)
	{
		final List<ItemWidget> out = new ArrayList<>();
		if (build < 0 || build >= s.wornSlots.length)
		{
			return out;
		}
		final int[] slots = s.wornSlots[build];
		for (int i = 0; i < slots.length; i++)
		{
			final Widget w = client.getWidget(slots[i]);
			final int itemId = itemIdOf(w);
			if (itemId > 0)
			{
				out.add(new ItemWidget(itemId, Math.max(1, w.getItemQuantity()), ArenaWidgets.WORN_SLOT_INDEX[i], w));
			}
		}
		return out;
	}

	/** All catalog rows for the build (every selectable item) — "to add" highlight targets. */
	List<ItemWidget> catalogItems(ArenaWidgets.Screen s, int build)
	{
		final List<ItemWidget> out = new ArrayList<>();
		if (build < 0 || build >= s.itemsList.length)
		{
			return out;
		}
		collectItems(client.getWidget(s.itemsList[build]), out);
		return out;
	}

	/** Owned supplies for the shown build: every item widget in the {@code _NINVENTORY} grid. */
	List<ItemWidget> inventoryItems(ArenaWidgets.Screen s, int build)
	{
		final List<ItemWidget> out = new ArrayList<>();
		if (build < 0 || build >= s.inventory.length)
		{
			return out;
		}
		collectItems(client.getWidget(s.inventory[build]), out);
		return out;
	}

	String spellbookLabel(ArenaWidgets.Screen s, int build)
	{
		return SpellbookMismatchOverlay.spellbookLabel(spellbookWidget(s, build));
	}

	Widget spellbookWidget(ArenaWidgets.Screen s, int build)
	{
		if (build < 0 || build >= s.spellbookDisplay.length)
		{
			return null;
		}
		return client.getWidget(s.spellbookDisplay[build]);
	}

	/** Reads the live setup into a transient {@link Loadout} (no id/name). Null if no builder. */
	Loadout readSnapshot()
	{
		final ArenaWidgets.Screen s = openScreen();
		if (s == null)
		{
			return null;
		}
		final int build = activeBuild(s);

		final Loadout l = new Loadout();
		l.setBuild(build);
		l.setSpellbook(spellbookLabel(s, build));

		final List<Loadout.WornItem> worn = new ArrayList<>();
		for (ItemWidget iw : wornItems(s, build))
		{
			worn.add(new Loadout.WornItem(iw.slot, iw.itemId, iw.quantity));
		}
		l.setWorn(worn);

		final List<Loadout.InvItem> inv = new ArrayList<>();
		for (ItemWidget iw : inventoryItems(s, build))
		{
			inv.add(new Loadout.InvItem(iw.itemId, iw.quantity));
		}
		l.setInventory(inv);
		return l;
	}

	/** itemId -&gt; total quantity across worn + inventory for the shown build. */
	Map<Integer, Integer> currentBag(ArenaWidgets.Screen s, int build)
	{
		final Map<Integer, Integer> bag = new HashMap<>();
		for (ItemWidget iw : wornItems(s, build))
		{
			bag.merge(iw.itemId, iw.quantity, Integer::sum);
		}
		for (ItemWidget iw : inventoryItems(s, build))
		{
			bag.merge(iw.itemId, iw.quantity, Integer::sum);
		}
		return bag;
	}

	/**
	 * DFS the subtree from {@code root}, collecting every item-bearing widget. Skips
	 * hidden subtrees. Started directly at the catalog / inventory grid widget, so there
	 * is nothing to exclude.
	 */
	private void collectItems(Widget root, List<ItemWidget> out)
	{
		if (root == null)
		{
			return;
		}

		final Set<Widget> seen = Collections.newSetFromMap(new IdentityHashMap<>());
		final Deque<Widget> stack = new ArrayDeque<>();
		stack.push(root);
		while (!stack.isEmpty())
		{
			final Widget w = stack.pop();
			if (w == null || !seen.add(w) || w.isHidden())
			{
				continue;
			}

			final int itemId = w.getItemId();
			if (itemId > 0)
			{
				out.add(new ItemWidget(itemId, Math.max(1, w.getItemQuantity()), -1, w));
			}

			pushAll(stack, w.getDynamicChildren());
			pushAll(stack, w.getChildren());
			pushAll(stack, w.getNestedChildren());
		}
	}

	private static void pushAll(Deque<Widget> stack, Widget[] kids)
	{
		if (kids != null)
		{
			for (Widget k : kids)
			{
				if (k != null)
				{
					stack.push(k);
				}
			}
		}
	}

	private int itemIdOf(Widget w)
	{
		if (w == null)
		{
			return -1;
		}
		if (w.getItemId() > 0)
		{
			return w.getItemId();
		}
		final Widget[] kids = w.getChildren();
		if (kids != null)
		{
			for (Widget k : kids)
			{
				if (k != null && k.getItemId() > 0)
				{
					return k.getItemId();
				}
			}
		}
		return -1;
	}
}

package com.pvparena;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.Menu;
import net.runelite.api.MenuEntry;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;

/**
 * Feature 1 — shift-click discard.
 *
 * <p>On a loadout item whose default left-click is {@code Discard}, swap the left-click
 * so that without Shift it {@code Examine}s (harmless during drag-rearrange) and with
 * Shift it {@code Discard}s. The swap is a reorder of the existing entries, so nothing
 * is removed and a right-click Discard always works. Items whose default left-click is
 * not Discard are never touched.
 */
@Singleton
class ShiftClickDeleteHandler
{
	private static final String DISCARD = "Discard";
	private static final String EXAMINE = "Examine";

	// Interface groups of the two loadout builders. param1 of an item menu entry packs
	// its widget id; the high 16 bits are the group.
	private static final int STAGING_GROUP =
		WidgetUtil.componentToInterface(InterfaceID.PvpArenaStagingareaSupplies.UNIVERSE);
	private static final int UNRANKED_GROUP =
		WidgetUtil.componentToInterface(InterfaceID.PvpArenaUnrankedduel.UNIVERSE);

	enum Decision
	{
		/** Keep Discard as the left-click (Shift held: intentional deletion). */
		DISCARD_LEFT,
		/** Promote Examine to the left-click (no Shift: protect against misclicks). */
		EXAMINE_LEFT,
		/** Leave the menu as-is. */
		UNCHANGED
	}

	private final Client client;

	@Inject
	ShiftClickDeleteHandler(Client client)
	{
		this.client = client;
	}

	/**
	 * Pure swap decision (unit-tested). See DESIGN.md Feature 1.
	 *
	 * @param hasDiscardDefault the item's current default left-click is Discard
	 * @param hasExamine        an Examine entry exists for the same item
	 * @param shiftHeld         Shift is held
	 */
	static Decision desiredLeftClick(boolean hasDiscardDefault, boolean hasExamine, boolean shiftHeld)
	{
		if (!hasDiscardDefault)
		{
			// Not a left-click-discard item; never change its left-click.
			return Decision.UNCHANGED;
		}

		if (shiftHeld)
		{
			return Decision.DISCARD_LEFT;
		}

		// No Shift: promote Examine so a stray click can't discard. If there is nothing
		// benign to promote, leave Discard rather than inventing a no-op.
		return hasExamine ? Decision.EXAMINE_LEFT : Decision.UNCHANGED;
	}

	/**
	 * Reorders the current (closed-menu) entries so the left-click matches
	 * {@link #desiredLeftClick}. Called from {@code onPostMenuSort} after the world and
	 * config gates have passed.
	 */
	void applyLeftClickSwap()
	{
		final Menu menu = client.getMenu();
		final MenuEntry[] entries = menu.getMenuEntries();
		if (entries.length == 0)
		{
			return;
		}

		// The left-click action is the last entry (top of the menu).
		final int topIdx = entries.length - 1;
		final MenuEntry top = entries[topIdx];

		if (!isBuilderItemEntry(top))
		{
			return;
		}

		final boolean topIsDiscard = DISCARD.equalsIgnoreCase(top.getOption());
		final boolean topIsExamine = EXAMINE.equalsIgnoreCase(top.getOption());
		if (!topIsDiscard && !topIsExamine)
		{
			// Some other option is the default left-click: leave it alone.
			return;
		}

		// Find the Discard / Examine entries belonging to the same hovered widget.
		final int widgetId = top.getParam1();
		int discardIdx = -1;
		int examineIdx = -1;
		for (int i = topIdx; i >= 0; i--)
		{
			final MenuEntry e = entries[i];
			if (e.getParam1() != widgetId)
			{
				continue;
			}

			final String option = e.getOption();
			if (discardIdx < 0 && DISCARD.equalsIgnoreCase(option))
			{
				discardIdx = i;
			}
			else if (examineIdx < 0 && EXAMINE.equalsIgnoreCase(option))
			{
				examineIdx = i;
			}
		}

		// The natural top entry each tick reflects the game's default left-click, so
		// "default is Discard" holds exactly when Discard is currently on top.
		final Decision decision = desiredLeftClick(topIsDiscard, examineIdx >= 0, isShiftHeld());

		final int desiredIdx;
		switch (decision)
		{
			case EXAMINE_LEFT:
				desiredIdx = examineIdx;
				break;
			case DISCARD_LEFT:
				desiredIdx = discardIdx;
				break;
			default:
				return;
		}

		if (desiredIdx < 0 || desiredIdx == topIdx)
		{
			return;
		}

		// Move the desired entry into the left-click (top) slot.
		final MenuEntry desired = entries[desiredIdx];
		entries[desiredIdx] = entries[topIdx];
		entries[topIdx] = desired;
		menu.setMenuEntries(entries);
	}

	private boolean isBuilderItemEntry(MenuEntry entry)
	{
		final int group = WidgetUtil.componentToInterface(entry.getParam1());
		return group == STAGING_GROUP || group == UNRANKED_GROUP;
	}

	private boolean isShiftHeld()
	{
		return client.isKeyPressed(KeyCode.KC_SHIFT);
	}
}

package com.pvparena;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.Text;

/**
 * Feature 2 — spellbook mismatch.
 *
 * <p>While the unranked duel screen is open on a PvP Arena world and the local player's
 * spellbook differs from the opponent's, marks the player's spellbook display with a
 * warning icon (right-aligned inside it), and draws a red outline on the opponent's
 * spellbook display and the confirm button, plus the same warning icon on the confirm
 * button.
 *
 * <p>The player side is deliberately <em>not</em> outlined red: {@link LoadoutOverlay}
 * already outlines that same spellbook widget red for a loadout-vs-setup mismatch, so a
 * red outline here would be indistinguishable. The warning icon keeps the two causes
 * visually distinct.
 *
 * <p>The comparison is on the <b>display label text</b> (e.g. {@code "Ancient Magicks"}),
 * not varbit values: the loadout spellbook varbit uses a non-standard encoding
 * (Ancient=0, Standard=1, Lunar=2) and the opponent-spellbook varbit is unreliable
 * (shared with transmit-progress state). Both sides render the same label vocabulary,
 * so a string compare is encoding-proof and matches exactly what the player sees.
 * Fails quiet whenever either label is unavailable.
 */
class SpellbookMismatchOverlay extends Overlay
{
	private static final Color OUTLINE_COLOR = Color.RED;
	private static final Stroke OUTLINE_STROKE = new BasicStroke(2f);
	private static final int ICON_PADDING_RIGHT = 6;

	// Local player's three spellbook display widgets, indexed by build slot (A/B/C).
	private static final int[] PLAYER_SPELLBOOK_DISPLAYS = {
		InterfaceID.PvpArenaUnrankedduel._0SPELLBOOK_DISPLAY,
		InterfaceID.PvpArenaUnrankedduel._1SPELLBOOK_DISPLAY,
		InterfaceID.PvpArenaUnrankedduel._2SPELLBOOK_DISPLAY,
	};

	private final Client client;
	private final PvpArenaConfig config;
	private final PvpArenaPlugin plugin;

	private BufferedImage warningIcon;

	@Inject
	SpellbookMismatchOverlay(Client client, PvpArenaConfig config, PvpArenaPlugin plugin, SpriteManager spriteManager)
	{
		this.client = client;
		this.config = config;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		spriteManager.getSpriteAsync(SpriteID.PVP_WARNING_ICON, 0, img -> warningIcon = img);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.spellbookMismatch() || !plugin.inPvpArena())
		{
			return null;
		}

		// Interface-layer gate: only act when the unranked duel screen is loaded.
		final Widget root = client.getWidget(InterfaceID.PvpArenaUnrankedduel.UNIVERSE);
		if (root == null || root.isHidden())
		{
			return null;
		}

		final int build = client.getVarbitValue(VarbitID.PVPA_TRANSMIT_BUILD);
		final Widget player = playerSpellbookWidget(build);
		final Widget opponent = client.getWidget(InterfaceID.PvpArenaUnrankedduel.OPPONENTSPELLBOOK_DISPLAY);
		final Widget confirm = client.getWidget(InterfaceID.PvpArenaUnrankedduel.OPPONENT_CONFIRM);

		if (!isMismatch(spellbookLabel(player), spellbookLabel(opponent)))
		{
			return null;
		}

		g.setStroke(OUTLINE_STROKE);
		g.setColor(OUTLINE_COLOR);

		// The player's and opponent's displays live on separate tabs and are never
		// visible at once; each mark skips hidden widgets, so it shows on its own tab.
		// The player side gets the warning icon (not a red outline) to stay distinct
		// from LoadoutOverlay's red loadout-mismatch outline on the same widget.
		drawWarningIcon(g, player);
		outline(g, opponent);
		outline(g, confirm);
		drawWarningIcon(g, confirm);

		return null;
	}

	/**
	 * Pure mismatch decision (unit-tested). Case-insensitive label compare; fails quiet
	 * (returns false) whenever either label is null or blank.
	 */
	static boolean isMismatch(String playerBook, String opponentBook)
	{
		if (playerBook == null || opponentBook == null)
		{
			return false;
		}

		final String p = playerBook.trim();
		final String o = opponentBook.trim();
		if (p.isEmpty() || o.isEmpty())
		{
			return false;
		}

		return !p.equalsIgnoreCase(o);
	}

	private Widget playerSpellbookWidget(int build)
	{
		if (build < 0 || build >= PLAYER_SPELLBOOK_DISPLAYS.length)
		{
			return null;
		}
		return client.getWidget(PLAYER_SPELLBOOK_DISPLAYS[build]);
	}

	/**
	 * The spellbook label lives on a child of the display widget. Reads the widget's own
	 * text first, then the first non-empty child text. Returns null if none.
	 */
	static String spellbookLabel(Widget display)
	{
		if (display == null)
		{
			return null;
		}

		String text = display.getText();
		if (text == null || text.isEmpty())
		{
			final Widget[] children = display.getChildren();
			if (children != null)
			{
				for (Widget child : children)
				{
					if (child != null && child.getText() != null && !child.getText().isEmpty())
					{
						text = child.getText();
						break;
					}
				}
			}
		}

		return text == null ? null : Text.removeTags(text).trim();
	}

	private void outline(Graphics2D g, Widget widget)
	{
		if (widget == null || widget.isHidden())
		{
			return;
		}

		final Rectangle bounds = widget.getBounds();
		if (bounds != null)
		{
			g.draw(bounds);
		}
	}

	/** Draws the warning icon right-aligned inside {@code widget}, vertically centered. */
	private void drawWarningIcon(Graphics2D g, Widget widget)
	{
		if (warningIcon == null || widget == null || widget.isHidden())
		{
			return;
		}

		final Rectangle bounds = widget.getBounds();
		if (bounds == null)
		{
			return;
		}

		final int x = bounds.x + bounds.width - warningIcon.getWidth() - ICON_PADDING_RIGHT;
		final int y = bounds.y + (bounds.height - warningIcon.getHeight()) / 2;
		g.drawImage(warningIcon, x, y, null);
	}
}

package com.pvparena;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

/**
 * Unit spec for {@link CatalogFilter#itemIdSharingRow}, the pure lookup behind resolving which
 * catalog item an {@code Add} click targets (Feature 3). Confirmed in-game 2026-08-11: the click's
 * param0 is the dense index of a bare op hotspot (item id -1) that shares its {@code originalY} with
 * the row's icon widget; repack moves a row's widgets together and hides non-loadout rows, so the
 * clicked item is the non-hidden icon on the same {@code originalY}. Pure like {@link PendingAddsTest}.
 */
public class CatalogFilterTest
{
	private static final int DDS = 5698;
	private static final int SHARK = 385;
	private static final boolean SHOWN = false;
	private static final boolean HIDDEN = true;

	@Test
	public void resolvesTheIconSharingTheClickedRowY()
	{
		// One visible row at y=64: bare hotspot (-1) + icon (DDS) both on that originalY.
		final int[] ys = {64, 64};
		final int[] itemIds = {-1, DDS};
		final boolean[] hidden = {SHOWN, SHOWN};
		assertEquals(DDS, CatalogFilter.itemIdSharingRow(64, ys, itemIds, hidden));
	}

	@Test
	public void picksTheClickedRowNotAnotherVisibleRow()
	{
		// Two visible rows repacked to distinct Ys; the clicked hotspot's Y selects exactly one.
		final int[] ys = {0, 0, 32, 32};
		final int[] itemIds = {-1, DDS, -1, SHARK};
		final boolean[] hidden = {SHOWN, SHOWN, SHOWN, SHOWN};
		assertEquals(DDS, CatalogFilter.itemIdSharingRow(0, ys, itemIds, hidden));
		assertEquals(SHARK, CatalogFilter.itemIdSharingRow(32, ys, itemIds, hidden));
	}

	@Test
	public void skipsAHiddenRowCollidingOnTheSameY()
	{
		// A hidden (filtered-out) item kept its original Y, which collides with the clicked
		// visible row's repacked Y; only the visible icon must be returned.
		final int[] ys = {32, 32, 32};
		final int[] itemIds = {SHARK, -1, DDS}; // SHARK hidden, DDS the visible clicked row
		final boolean[] hidden = {HIDDEN, SHOWN, SHOWN};
		assertEquals(DDS, CatalogFilter.itemIdSharingRow(32, ys, itemIds, hidden));
	}

	@Test
	public void returnsMinusOneWhenNoVisibleItemSharesTheRow()
	{
		// Row holds only the hotspot; the only item on that Y is hidden.
		final int[] ys = {96, 96};
		final int[] itemIds = {-1, DDS};
		final boolean[] hidden = {SHOWN, HIDDEN};
		assertEquals(-1, CatalogFilter.itemIdSharingRow(96, ys, itemIds, hidden));
	}

	@Test
	public void returnsMinusOneForEmptyRows()
	{
		assertEquals(-1, CatalogFilter.itemIdSharingRow(0, new int[0], new int[0], new boolean[0]));
	}
}

package com.pvparena;

import com.google.gson.Gson;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Base64;
import java.util.Collections;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import org.junit.Test;

public class LoadoutCodecTest
{
	private static final int AGS = 11802;
	private static final int BREW = 6685;
	private static final int PPOT = 2434;

	private static final String ANCIENT = "Ancient Magicks";

	/**
	 * A real v1 code (a full "max nh" loadout) captured before v2 existed, kept verbatim as a
	 * back-compat fixture. Never regenerate this from the current encoder: its value is being a
	 * frozen witness that codes already in the wild still decode.
	 */
	private static final String FROZEN_V1 =
		"pvpa-loadout-v1:";

	private final LoadoutCodec codec = new LoadoutCodec(new Gson());

	private static Loadout sample()
	{
		final Loadout l = new Loadout();
		l.setId("original-id");
		l.setName("Pure rush");
		l.setBuild(2);
		l.setSpellbook(ANCIENT);
		l.setWorn(Collections.singletonList(new Loadout.WornItem(3, AGS, 1)));
		l.setInventory(Arrays.asList(new Loadout.InvItem(BREW, 6), new Loadout.InvItem(PPOT, 4)));
		l.setSavedAt(123456789L);
		return l;
	}

	@Test
	public void roundTripPreservesContent() throws LoadoutCodecException
	{
		final Loadout original = sample();
		final Loadout decoded = codec.decode(codec.encode(original));

		assertEquals(original.getName(), decoded.getName());
		assertEquals(original.getBuild(), decoded.getBuild());
		assertEquals(original.getSpellbook(), decoded.getSpellbook());
		assertEquals(original.getWorn(), decoded.getWorn());
		assertEquals(original.getInventory(), decoded.getInventory());
	}

	@Test
	public void decodeMintsFreshIdentity() throws LoadoutCodecException
	{
		// id/savedAt are not carried; the caller (LoadoutManager.add) mints them.
		final Loadout decoded = codec.decode(codec.encode(sample()));
		assertNull(decoded.getId());
		assertEquals(0L, decoded.getSavedAt());
	}

	@Test
	public void roundTripCarriesNullSpellbook() throws LoadoutCodecException
	{
		final Loadout original = sample();
		original.setSpellbook(null);
		final Loadout decoded = codec.decode(codec.encode(original));
		assertNull(decoded.getSpellbook());
	}

	@Test
	public void encodedCodeCarriesTheVersionedPrefix()
	{
		assertTrue(codec.encode(sample()).startsWith("pvpa-loadout-v2:"));
	}

	@Test
	public void rejectsBadPrefix()
	{
		expectInvalid("just some random clipboard text");
	}

	@Test
	public void rejectsNullInput()
	{
		expectInvalid(null);
	}

	@Test
	public void rejectsBadBase64()
	{
		expectInvalid("pvpa-loadout-v1:@@not-valid-base64@@");
	}

	@Test
	public void rejectsBadJson()
	{
		expectInvalid("pvpa-loadout-v1:" + base64("{ this is not json"));
	}

	@Test
	public void rejectsEmptyLoadout()
	{
		final Loadout empty = new Loadout();
		empty.setName("empty");
		// No worn and no inventory -> nothing to share.
		expectInvalid(codec.encode(empty));
	}

	@Test
	public void newerVersionIsDistinctFromInvalid()
	{
		// A recognized-but-newer version (beyond what this plugin writes) is a distinct signal.
		final String vNext = codec.encode(sample()).replaceFirst("^pvpa-loadout-v2:", "pvpa-loadout-v3:");
		try
		{
			codec.decode(vNext);
			fail("expected a newer-version rejection");
		}
		catch (LoadoutCodecException e)
		{
			assertEquals(LoadoutCodecException.Reason.NEWER_VERSION, e.getReason());
		}
	}

	@Test
	public void decodesFrozenV1Code() throws LoadoutCodecException
	{
		// Back-compat: a real v1 code shared before v2 existed must still import. Frozen literal
		// (not produced by the current encoder), so this cannot silently drift with the format.
		final Loadout decoded = codec.decode(FROZEN_V1);

		assertEquals("max nh", decoded.getName());
		assertEquals(0, decoded.getBuild());
		assertEquals("Ancient Magicks", decoded.getSpellbook());
		assertEquals(11, decoded.getWorn().size());

		// Matching is bag-based; the v1 code carried un-collapsed inventory dupes.
		final Map<Integer, Integer> bag = decoded.bag();
		assertEquals(Integer.valueOf(9), bag.get(13441)); // sharks
		assertEquals(Integer.valueOf(4), bag.get(10925)); // karambwans
		assertEquals(Integer.valueOf(3), bag.get(6685));  // saradomin brews
	}

	@Test
	public void v1AndV2RoundTripToTheSameLoadout() throws LoadoutCodecException
	{
		// The v2 re-encode of the frozen v1 code decodes to an equivalent bag (format change is
		// lossless for matching).
		final Loadout fromV1 = codec.decode(FROZEN_V1);
		final Loadout viaV2 = codec.decode(codec.encode(fromV1));
		assertEquals(fromV1.bag(), viaV2.bag());
		assertEquals(fromV1.getSpellbook(), viaV2.getSpellbook());
	}

	@Test
	public void rejectsCorruptV2Payload()
	{
		// Valid Base64 but not a DEFLATE stream -> inflate fails -> invalid, never a crash.
		expectInvalid("pvpa-loadout-v2:" + base64("not a deflate stream at all"));
	}

	@Test
	public void encodeCollapsesDuplicateInventoryItems() throws LoadoutCodecException
	{
		// Four brews across four inventory slots (as SetupReader captures them) must serialize
		// as a single qty-4 entry, and the decoded inventory reflects the collapse.
		final Loadout spread = new Loadout();
		spread.setName("Spread");
		spread.setInventory(Arrays.asList(
			new Loadout.InvItem(BREW, 1),
			new Loadout.InvItem(PPOT, 1),
			new Loadout.InvItem(BREW, 1),
			new Loadout.InvItem(BREW, 1),
			new Loadout.InvItem(BREW, 1)));

		final Loadout decoded = codec.decode(codec.encode(spread));

		// First-seen order preserved: brew (seen first) then prayer potion.
		assertEquals(Arrays.asList(
			new Loadout.InvItem(BREW, 4),
			new Loadout.InvItem(PPOT, 1)), decoded.getInventory());
	}

	@Test
	public void collapsePreservesBagTotals() throws LoadoutCodecException
	{
		final Loadout spread = new Loadout();
		spread.setName("Spread");
		spread.setInventory(Arrays.asList(
			new Loadout.InvItem(BREW, 1),
			new Loadout.InvItem(BREW, 1),
			new Loadout.InvItem(PPOT, 4)));

		// Matching goes through bag(); collapsing must not change it.
		assertEquals(spread.bag(), codec.decode(codec.encode(spread)).bag());
	}

	@Test
	public void encodeIsDeterministic()
	{
		// Byte-identical codes for the same loadout (LinkedHashMap first-seen order).
		final Loadout original = sample();
		assertEquals(codec.encode(original), codec.encode(original));
	}

	private static String base64(String s)
	{
		return Base64.getEncoder().encodeToString(s.getBytes(StandardCharsets.UTF_8));
	}

	private void expectInvalid(String raw)
	{
		try
		{
			codec.decode(raw);
			fail("expected an invalid-code rejection for: " + raw);
		}
		catch (LoadoutCodecException e)
		{
			assertEquals(LoadoutCodecException.Reason.INVALID, e.getReason());
		}
	}
}

package com.pvparena;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class LoadoutDiffTest
{
	private static final int BREW = 6685;
	private static final int PPOT = 2434;
	private static final int KARAMBWAN = 3144;
	private static final int DDS = 5698;

	private static final String ANCIENT = "Ancient Magicks";
	private static final String STANDARD = "Standard Spellbook";

	private static Map<Integer, Integer> bag(int... itemThenQtyPairs)
	{
		final Map<Integer, Integer> m = new HashMap<>();
		for (int i = 0; i < itemThenQtyPairs.length; i += 2)
		{
			m.put(itemThenQtyPairs[i], itemThenQtyPairs[i + 1]);
		}
		return m;
	}

	@Test
	public void needsMoreOfAnItem()
	{
		// Q4 #1: want 6 brews, have 2 -> add 4.
		final LoadoutDiff diff = LoadoutDiff.compute(bag(BREW, 6), bag(BREW, 2), ANCIENT, ANCIENT);
		assertEquals(4, diff.needFor(BREW));
		assertTrue(diff.excess().isEmpty());
		assertFalse(diff.isFullMatch());
	}

	@Test
	public void tooManyOfAnItemIsExcess()
	{
		// Q4 #2: want 6 brews, have 8 -> 2 excess, nothing to add.
		final LoadoutDiff diff = LoadoutDiff.compute(bag(BREW, 6), bag(BREW, 8), ANCIENT, ANCIENT);
		assertTrue(diff.toAdd().isEmpty());
		assertEquals(Integer.valueOf(2), diff.excess().get(BREW));
		assertTrue(diff.isExcess(BREW));
		assertFalse(diff.isFullMatch());
	}

	@Test
	public void unwantedItemIsExcess()
	{
		// Q4 #3: a karambwan the loadout does not include.
		final LoadoutDiff diff = LoadoutDiff.compute(bag(BREW, 6), bag(BREW, 6, KARAMBWAN, 1), ANCIENT, ANCIENT);
		assertTrue(diff.toAdd().isEmpty());
		assertEquals(Integer.valueOf(1), diff.excess().get(KARAMBWAN));
		assertFalse(diff.isFullMatch());
	}

	@Test
	public void exactMatchIsFullMatch()
	{
		final LoadoutDiff diff = LoadoutDiff.compute(bag(BREW, 6, PPOT, 4), bag(BREW, 6, PPOT, 4), ANCIENT, ANCIENT);
		assertTrue(diff.toAdd().isEmpty());
		assertTrue(diff.excess().isEmpty());
		assertFalse(diff.spellbookMismatch());
		assertTrue(diff.isFullMatch());
	}

	@Test
	public void spellbookMismatchBlocksFullMatch()
	{
		// Q14 (B): items match but spellbook differs -> not a full match.
		final LoadoutDiff diff = LoadoutDiff.compute(bag(BREW, 6), bag(BREW, 6), ANCIENT, STANDARD);
		assertTrue(diff.toAdd().isEmpty());
		assertTrue(diff.excess().isEmpty());
		assertTrue(diff.spellbookMismatch());
		assertFalse(diff.isFullMatch());
	}

	@Test
	public void unknownSpellbookIsNotFlagged()
	{
		// Fail-quiet: a null loadout spellbook never flags, so items-equal == full match.
		final LoadoutDiff diff = LoadoutDiff.compute(bag(BREW, 6), bag(BREW, 6), null, STANDARD);
		assertFalse(diff.spellbookMismatch());
		assertTrue(diff.isFullMatch());
	}

	@Test
	public void bagFlattensWornAndInventory()
	{
		// Q4 #4 (option b): a DDS worn and a DDS in inventory produce the same bag, so
		// either placement satisfies "want 1 DDS" -> full match.
		final Loadout worn = new Loadout();
		worn.setWorn(Collections.singletonList(new Loadout.WornItem(3, DDS, 1)));

		final Loadout inInv = new Loadout();
		inInv.setInventory(Collections.singletonList(new Loadout.InvItem(DDS, 1)));

		assertEquals(worn.bag(), inInv.bag());
		assertTrue(LoadoutDiff.compute(worn.bag(), inInv.bag(), null, null).isFullMatch());
	}

	@Test
	public void bagSumsDuplicateItemAcrossWornAndInventory()
	{
		final Loadout l = new Loadout();
		l.setWorn(Collections.singletonList(new Loadout.WornItem(13, BREW, 1)));
		l.setInventory(Arrays.asList(new Loadout.InvItem(BREW, 5), new Loadout.InvItem(PPOT, 4)));
		assertEquals(Integer.valueOf(6), l.bag().get(BREW));
		assertEquals(Integer.valueOf(4), l.bag().get(PPOT));
		assertEquals(10, l.itemCount());
	}
}

package com.pvparena;

import java.lang.reflect.Method;
import java.util.HashSet;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import static org.junit.Assert.assertFalse;
import org.junit.Test;

/**
 * Regression guard for the loadouts panel-disappears-on-save bug: the loadout list was
 * persisted under the same {@code pvparena} config key ({@code "loadouts"}) as the feature
 * toggle {@link PvpArenaConfig#loadouts()}, so saving a loadout overwrote the boolean and
 * {@code updateNav()} tore the panel out. A storage key must never collide with a
 * {@link ConfigItem} key in the same group.
 */
public class LoadoutStorageKeyTest
{
	private static Set<String> configItemKeys()
	{
		final Set<String> keys = new HashSet<>();
		for (Method m : PvpArenaConfig.class.getMethods())
		{
			final ConfigItem ci = m.getAnnotation(ConfigItem.class);
			if (ci != null)
			{
				keys.add(ci.keyName());
			}
		}
		return keys;
	}

	@Test
	public void storageKeyDoesNotCollideWithAConfigItem()
	{
		assertFalse(
			"LoadoutManager.KEY \"" + LoadoutManager.KEY + "\" collides with a PvpArenaConfig @ConfigItem keyName; "
				+ "saving loadouts would overwrite that config value",
			configItemKeys().contains(LoadoutManager.KEY));
	}
}

package com.pvparena;

import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Unit spec for {@link PendingAdds}, the optimistic-add reconciler behind the catalog
 * filter (Feature 3): a click is credited immediately so the filtered row disappears on
 * the next {@code ClientTick} instead of waiting a game tick for the lagging inventory
 * read. Pure like {@link LoadoutDiffTest}; no client deps (the game tick is passed in).
 *
 * <p>A prediction retires by one of two paths: the <b>fast path</b> — the real read grows to
 * meet it — or the <b>TTL backstop</b> — {@code TTL_TICKS} (2) game ticks past its last click,
 * for when the add never lands because the item was removed again. Cases that only exercise the
 * fast path hold the tick constant (0); the TTL cases advance it.
 */
public class PendingAddsTest
{
	private static final int DDS = 5698;
	private static final int SHARK = 385;
	private static final int BREW = 6685;

	private static Map<Integer, Integer> bag(int... itemThenQtyPairs)
	{
		final Map<Integer, Integer> m = new HashMap<>();
		for (int i = 0; i < itemThenQtyPairs.length; i += 2)
		{
			m.put(itemThenQtyPairs[i], itemThenQtyPairs[i + 1]);
		}
		return m;
	}

	@Test
	public void recordCreditsItemImmediately()
	{
		// The whole point: +1 shows up before the real read has it (empty current bag).
		final PendingAdds p = new PendingAdds();
		p.record(DDS, 0);
		assertEquals(Integer.valueOf(1), p.effectiveBag(bag(), 0).get(DDS));
	}

	@Test
	public void predictionRetiresWhenRealReadCatchesUp()
	{
		final PendingAdds p = new PendingAdds();
		p.record(DDS, 0);
		// Frame 1: real still lagging (pre-add). Baseline captured at 0, prediction stands.
		assertEquals(Integer.valueOf(1), p.effectiveBag(bag(), 0).get(DDS));
		// Frame N: the add landed in the real read. Prediction retires, no double-count.
		assertEquals(Integer.valueOf(1), p.effectiveBag(bag(DDS, 1), 0).get(DDS));
		// Prediction is gone: later reads pass through untouched.
		assertEquals(Integer.valueOf(1), p.effectiveBag(bag(DDS, 1), 0).get(DDS));
	}

	@Test
	public void partialStackStaysPredictedUntilRealFullyCatchesUp()
	{
		// Want three sharks from empty: three rapid clicks, real lags then lands.
		final PendingAdds p = new PendingAdds();
		p.record(SHARK, 0);
		p.record(SHARK, 0);
		p.record(SHARK, 0);
		assertEquals(Integer.valueOf(3), p.effectiveBag(bag(), 0).get(SHARK));          // 0 real + 3 predicted
		assertEquals(Integer.valueOf(3), p.effectiveBag(bag(SHARK, 1), 0).get(SHARK));  // 1 real + 2 predicted
		assertEquals(Integer.valueOf(3), p.effectiveBag(bag(SHARK, 2), 0).get(SHARK));  // 2 real + 1 predicted
		assertEquals(Integer.valueOf(3), p.effectiveBag(bag(SHARK, 3), 0).get(SHARK));  // 3 real, prediction retired
		assertEquals(Integer.valueOf(3), p.effectiveBag(bag(SHARK, 3), 0).get(SHARK));  // pure passthrough
	}

	@Test
	public void baselineIsTheRealCountWhenTheAddBegan()
	{
		// Topping up a held stack: baseline-diff must credit against the real count, not zero.
		final PendingAdds p = new PendingAdds();
		p.record(BREW, 0);
		assertEquals(Integer.valueOf(3), p.effectiveBag(bag(BREW, 2), 0).get(BREW)); // baseline 2, +1 predicted
		assertEquals(Integer.valueOf(3), p.effectiveBag(bag(BREW, 3), 0).get(BREW)); // real caught up, retired
		assertEquals(Integer.valueOf(3), p.effectiveBag(bag(BREW, 3), 0).get(BREW)); // passthrough
	}

	@Test
	public void predictionExpiresAfterTtlWhenReadNeverCatchesUp()
	{
		// The add never lands in the read (item removed again). The add-only diff can't see the
		// retraction, so the TTL backstop retires the prediction 2 ticks after the click — the
		// row returns instead of sticking forever.
		final PendingAdds p = new PendingAdds();
		p.record(DDS, 0);
		assertEquals(Integer.valueOf(1), p.effectiveBag(bag(), 0).get(DDS)); // t0: live
		assertEquals(Integer.valueOf(1), p.effectiveBag(bag(), 1).get(DDS)); // t1: within TTL
		assertNull(p.effectiveBag(bag(), 2).get(DDS));                       // t2: TTL expired
	}

	@Test
	public void ttlRefreshesOnEachClickSoAStackFillNeverExpiresMidFill()
	{
		// Clicking a stack across several ticks: each click refreshes the TTL, so the prediction
		// survives even though the first click is now older than the TTL.
		final PendingAdds p = new PendingAdds();
		p.record(SHARK, 0);
		p.record(SHARK, 1);
		p.record(SHARK, 2);
		// t3 is 3 ticks past the first click but only 1 past the last: still live.
		assertEquals(Integer.valueOf(3), p.effectiveBag(bag(), 3).get(SHARK));
		// No further clicks: expires 2 ticks after the last one (2 + 2 = 4).
		assertNull(p.effectiveBag(bag(), 4).get(SHARK));
	}

	@Test
	public void removalHealsViaTtlAfterTheAddNeverLands()
	{
		// Held one DDS, want a second: an Add click credits +1 on top of the real 1.
		final PendingAdds p = new PendingAdds();
		p.record(DDS, 0);
		assertEquals(Integer.valueOf(2), p.effectiveBag(bag(DDS, 1), 0).get(DDS)); // 1 real + 1 predicted

		// Player removes the held DDS before the add is observed: the read drops to 0. The
		// add-only diff can't reconcile a decrease, so the prediction lingers within the TTL
		// window (the ~2-tick removal-heal delay), then the TTL retires it and the row returns.
		assertEquals(Integer.valueOf(2), p.effectiveBag(bag(), 1).get(DDS)); // t1: still predicted
		assertNull(p.effectiveBag(bag(), 2).get(DDS));                       // t2: healed
	}

	@Test
	public void clearWipesEveryPrediction()
	{
		final PendingAdds p = new PendingAdds();
		p.record(DDS, 0);
		p.clear();
		assertTrue(p.effectiveBag(bag(), 0).isEmpty());
	}

	@Test
	public void effectiveBagDoesNotMutateTheInputBag()
	{
		final PendingAdds p = new PendingAdds();
		p.record(DDS, 0);
		final Map<Integer, Integer> current = bag();
		p.effectiveBag(current, 0);
		assertNull(current.get(DDS));
		assertTrue(current.isEmpty());
	}
}

